INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-13', '누가복음', '22장 51~60절', '예수께서 잡히시다', '누가복음 22장
51   예수께서 일러 이르시되 이것까지 참으라 하시고 그 귀를 만져 낫게 하시더라
52   예수께서 그 잡으러 온 대제사장들과 성전의 경비대장들과 장로들에게 이르시되 너희가 강도를 잡는 것 같이 검과 몽치를 가지고 나왔느냐
53   내가 날마다 너희와 함께 성전에 있을 때에 내게 손을 대지 아니하였도다 그러나 이제는 너희 때요 어둠의 권세로다 하시더라
54   예수를 잡아 끌고 대제사장의 집으로 들어갈새 베드로가 멀찍이 따라가니라
55   사람들이 뜰 가운데 불을 피우고 함께 앉았는지라 베드로도 그 가운데 앉았더니
56   한 여종이 베드로의 불빛을 향하여 앉은 것을 보고 주목하여 이르되 이 사람도 그와 함께 있었느니라 하니
57   베드로가 부인하여 이르되 이 여자여 내가 그를 알지 못하노라 하더라
58   조금 후에 다른 사람이 보고 이르되 너도 그 도당이라 하거늘 베드로가 이르되 이 사람아 나는 아니로라 하더라
59   한 시간쯤 있다가 또 한 사람이 장담하여 이르되 이는 갈릴리 사람이니 참으로 그와 함께 있었느니라
60   베드로가 이르되 이 사람아 나는 네가 하는 말을 알지 못하노라고 아직 말하고 있을 때에 닭이 곧 울더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
예수: 51, 52, 54
베드로: 54, 55, 56, 57, 58, 60
이 사람아 나는: 58, 60

4.주제 만들기: 예수께서 잡히시다

5.하나님 찾기(관찰)
- 귀를 고쳐주신 예수님
- 대제사장의 집으로 잡혀가신 예수님

6.인간 찾기(관찰)
- 귀를 고침 받은 종
- 예수님을 잡아가는 대제사장들과 일행들
- 예수님을 멀찍이 따라가는 베드로
- 예수님을 알지 못한다고 말하는 베드로

7.하나님 찾기(해석)
- 비록 자신을 잡아가는 자라도 상한 귀를 고쳐주시는 예수님
- 인간을 향한 그의 사랑은 끝이 없음을 알 수 있다.

- 십자가의 때가 되었기에 저항하지 않고 순순히 잡혀가시는 예수님
- 겟세마네 동산에서 피, 땀, 눈물로 기도하셨기에 잡힘도 제자들의 도망도 채찍질도 그리고 십자가까지도 감당할 준비가 되셨다.
 
8.인간 찾기(해석)
- 귀를 고침 받은 종은 예수님의 놀라운 능력을 직접 체험하고 감동했을 것이다.
- 대제사장들과 일당들은 의기양양하게 예수님을 잡아갔을 것이다.
- 그들은 아마도 예수님을 혼내줄 생각에 기분이 매우 들떠 있었을 것이다.

- 베드로는 두려움에 떨려 멀찍이 떨어져 예수님을 따라갔고,
- 대제사장의 집 뜰까지 조심히 들어가 예수님을 바라봤다.
- 죽음까지도 함께 하겠다고 자신 있게 말했으나, 일이 닥치자 베드로는 너무나 작아졌다.
- 아마도 베드로는 세상에서 예수님을 가장 사랑하는 자였고, 동시에 세상에서 가장 용기를 낸 자였다.
- 그러나 인간의 사랑과 용기는 너무나 초라할 뿐이다. 

- 예수님을 모른다고 세 번째 부인하는 말을 하고 있을 때 닭이 울었다.
- 베드로에게 예수님의 말씀이 번개같이 스쳐 지나갔을 것이고, 수치심과 죄스러움에 무너져 내렸을 것이다.
- 그러나 베드로에게는 한 가지 희망이 있으니, 예수님께서 믿음을 잃지 않도록 기도를 해주신 것이다. 
- 베드로는 크게 실패했으나 믿음을 잃지 않고 더욱 강한 믿음으로 형제들을 굳세게 하는 자가 될 것이다.

9.적용(나) 
- 나의 사랑과 용기는, 나의 의지와 더불어 너무나 보잘것없는 것이다.
- 예수님의 기도와 성령님의 도우심으로 내게 사랑과 용기가 주어지기를 바랄 뿐이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-14', '누가복음', '22장 61~71절', '&nbsp;', '[눅22:61-71]
61 주께서 돌이켜 베드로를 보시니 베드로가 주의 말씀 곧 오늘 닭 울기 전에 네가 세 번 나를 부인하리라 하심이 생각나서
62 밖에 나가서 심히 통곡하니라
63 지키는 사람들이 예수를 희롱하고 때리며
64 그의 눈을 가리고 물어 이르되 선지자 노릇 하라 너를 친 자가 누구냐 하고
65 이 외에도 많은 말로 욕하더라
66 날이 새매 백성의 장로들 곧 대제사장들과 서기관들이 모여서 예수를 그 공회로 끌어들여
67 이르되 네가 그리스도이거든 우리에게 말하라 대답하시되 내가 말할지라도 너희가 믿지 아니할 것이요
68 내가 물어도 너희가 대답하지 아니할 것이니라
69 그러나 이제부터는 인자가 하나님의 권능의 우편에 앉아 있으리라 하시니
70 다 이르되 그러면 네가 하나님의 아들이냐 대답하시되 너희들이 내가 그라고 말하고 있느니라
71 그들이 이르되 어찌 더 증거를 요구하리요 우리가 친히 그 입에서 들었노라 하더라

