1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 예수(63,66절)
- 베드로(61절)
- 말하다(67,70절)

4. 주제만들기: 

5. 하나님 찾기 (관찰)
- 예수님을 자신을 세 번 부인한 베드로를 고개를 돌이켜 쳐다보심
- 예수님은 지키는 자들로부터 희롱과 욕설과 고문을 당하심
- 예수님은 대제사장의 질문에 내가 말할지라도 너희가 믿지 않을 것이고 내가 물어도 너희가 대답하지 않을거라 말씀하심
- 예수님은 이제부터 인자가 하나님의 권능의 우편에 앉아 계실 것이라고 말하자 하나님의 아들이냐는 대제사장의 질문에 너희들이 내가 그라고 말하고 있다 말씀하심

6. 인간 찾기 (관찰)
- 베드로는 예수님을 세 번 부인했고, 자신을 바라보는 예수님을 보고 밖으로 나가 통곡함
- 예수님을 지키는 자들은 눈을 가리고 예수님을 때린 후 선지자와 같이 누가 때렸는지 맞춰보라고 조롱함
- 대제사장들과 서기관은 공회로 끌어들여 예수님께 질문함
- 네가 그리스도이거든 우리에게 말하라, 네가 하나님의 아들이냐?
- 그들은 예수님의 답변에 오히려 이보다 더한 증거가 있냐며 그가 친히 말했다고 말함 

7. 하나님 찾기 (해석) 
- 예수님은 자신을 세 번 부인한 베드로를 돌이켜 쳐다보셨다. 
- 예수님께서 베드로를 쳐다보신 것은 베드로를 사랑하기 때문일 것이다. 
- 만약 베드로에게 세 번 부인할 것을 미리 알려주지 않았다면 어떻게 됐을까? 예수님이 부활하시고 베드로를 만났을 때 베드로는 믿음과 용기가 완전히 회복되지 못했을 것이다.
- 예수님을 부인한 사실이 베드로를 넘어뜨리는 상황이 반복되었을 것이다. 그러나 예수님께서 돌이켜 보심으로 베드로를 완전히 회복시킬 수 있는 기적의 스토리가 완성되었다.

- 예수님은 자신을 지키는 자들의 고문과 희롱과 욕설을 감당하셨다. 
- 우리를 죄에서 회복시키고, 구원을 하시고자 모진 고문을 감당하셨다. 
- 이 세상 어느 누가, 타인을 위하여 자신의 목숨을 내 놓을 수 있을까?

- 예수님은 대제사장의 질문에 대답했다.
- 하지만 예수님께서 하신 대답은 예수님께서 사역을 하며 반복적으로 주었던 메시지였다. 
- 이미 예수님을 죽이고자 마음먹은 자들에게 예수님을 더 이상 질문하지 않는다.
- 그리고 분명히 말씀하신다. 자신의 구원자이고, 하나님의 아들임을  

8. 인간(해석):
- 대제사장은 하나님을 믿지 않았다. 그들은 자신의 지위와 명예를 선택했다.
- 예수님의 말씀은 귀에 들어오지 않았고, 시기와 질투와 두려움에 예수님을 제거하고 싶을 것이다. 
- 우리 중 누구라도 유다와 대제사장 같은 어리석은 선택을 하는 존재가 될 수 있다. 
- 하나님을 알고, 예수님을 알지만 사탄은 치밀하고 집요하게 넘어뜨리려 한다. 
- 우리가 넘어지지 않으려면 말씀과 기도로 단단히 훈련이 되어야 한다. 
- 세상이 더 악해지고 교회가 하나님을 진정 믿고 있는지 헷갈리는 요즘, 우리에게 3331 큐티는 생명의 말씀일 것이다.

9. 적용(나): 
- 베드로 같은 나를 사랑해주시는 하나님의 은혜에 감사하며 받은 사랑을 전하는 사람이 되어야겠다.
- 진리와 진실은 감춰지고 악이 만연한 시대에 말씀과 기도로 바로 서야겠다.

10. 영적터치(단어/구절)
67절 내가 말할지라도 너희가 믿지 아니할 것이요

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-15', '누가복음', '23장 1~10절', '&nbsp;', '(누가복음 23장)
1.  무리가 다 일어나 예수를 빌라도에게 끌고 가서
2. 고발하여 이르되 우리가 이 사람을 보매 우리 백성을 미혹하고 가이사에게 세금 바치는 것을 금하며 자칭 왕 그리스도라 하더이다 하니
3. 빌라도가 예수께 물어 이르되 네가 유대인의 왕이냐 대답하여 이르시되 네 말이 옳도다
4. 빌라도가 대제사장들과 무리에게 이르되 내가 보니 이 사람에게 죄가 없도다 하니
5. 무리가 더욱 강하게 말하되 그가 온 유대에서 가르치고 갈릴리에서부터 시작하여 여기까지 와서 백성을 소동하게 하나이다
6. 빌라도가 듣고 그가 갈릴리 사람이냐 물어
7. 헤롯의 관할에 속한 줄을 알고 헤롯에게 보내니 그 때에 헤롯이 예루살렘에 있더라
8.  헤롯이 예수를 보고 매우 기뻐하니 이는 그의 소문을 들었으므로 보고자 한 지 오래였고 또한 무엇이나 이적 행하심을 볼까 바랐던 연고러라
9. 여러 말로 물으나 아무 말도 대답하지 아니하시니
10. 대제사장들과 서기관들이 서서 힘써 고발하더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2025년 8월16일 
누가복음 23장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
빌라도: 1절 3절 4절 6절 
예수: 1절 3절 8절 
무리: 1절 4절 5절
고발: 2절 10절
왕: 2절 3절 
미혹/소동: 2절 5절

4.주제 만들기: 
예수께  묻는 빌라도.

5.하나님 찾기 (관찰)
사람들로 인하여 빌라도 앞에 끌려오신 예수.
빌라도 묻는 말에 대답하시는 예수.
헤롯에게 다시 끌려오신 예수.
헤롯의 묻는 말에 대답을 안하시는 예수.
 
6.인간 찾기(관찰)
예수를 빌라도 에게 끌고온 무리.
예수께 묻는 빌라도.
헤롯에게 예수를 보낸 빌라도
(이때까지 빌라도는 예수가 죄인이라 생각 안함)
예수가 죄인이라 강력하게 주장하는 무리.

7.하나님 찾기(해석)
예수님을 인간적인 측면에서 보면 정말 견디기 힘든 고초를 받고 계신다. 

사랑하는 제자들은 다 도망갔고 한때 자신에게 혜택을 받고 따랐던 수많은 사람이 이제는 등을 돌리고 자신을 해하는 최고의 고발자가 되었다. 

그러한 괴롭고 외로운 상황에서도 예수님은 자신의 계획대로 모든 고통을 묵묵히 받으셨다. 

무리가 자신을 끌고 가면 그대로 끌려가시고 빌라도가 심문하면 받으셨다. 그리고 헤롯에게 데리고 가면 말대꾸도 없이 따랐다. 

마치 힘없는 어린양처럼 움직이셨다. 주님이 이 고난을 견디신 것은 단 한 가지 인간을 구원하기 위해서이다. 

나는 과연 한 영혼을 위하여 이렇게 고난을 감당하며 견딜 수 있을? 그 사랑을 생각하면 주님 때문에 나도 때때로 오는 인생의 무게를 기쁨으로 잘 견뎌내야겠다. 

또한 주님의 은혜를 받지 못하면 나 역시 주님의 영광을 가리는 사람이 될 수 있음에 더욱 경각심을 가져야겠다. 그러므로 매일 은혜의 자리에 더욱 나가는 것이 얼마나 중요한지 알게 된다. 

8. 인간 찾기(해석)
사도신경에 이름이 기록된 본디오빌라도는 시대의 모든 사람에게 알려진 예수를 죽인 사람으로 각인된 사람이다. 오늘 말씀을 얼핏 보면 빌라도는 처음부터 예수를 죽일 마음은 없는 듯 보인다.

4절에 보면 "내가 보니 이 사람에게 죄가 없도다 하니" 기록된 것을 보면 알 수 있다. 빌라도는 나름 회피하려고 분봉 왕인 헤롯에게 예수를 보냈다. 그나마 헤롯에게 자신을 책임을 회피했지만 나름 당시 대 로마의 총독인 빌라도가 이렇게 할 수밖에 없었던 것은 군중의 소리 때문이었을 것이다.

많은 무리가 일어나 예수를 죽이라고 고발했다. 심지어는 거짓된 내용까지 포함했다. 그들은 로마의 최고 권력자인 황제 가이사의 권위 약화를 주장하면서까지 예수를 몰아세웠다. 

불과 얼마 전까지만 해도 예수를 따랐던 무리가 지금은 돌변하였다. 사탄은 거짓말의 대가인데 한 영혼을 파괴하거나 무너뜨릴 때는 왜곡된 사실을 동원하여 공격함을 볼 수 있다. 

요즘 언론에나 조회수를 올리기 위해 자극적으로 왜곡된 기사를 쏟아내어 피해를 본 적지 않은 사람들이 스스로 목숨을 끊는 경우들이 있음을 뒤늦게 본다. 

진실이 밝혀져도 누구 하나 책임지는 사람도 없다. 이러한 방법은 예나 지금이나 사탄이 사람들을 조정하고 있음을 알 수 있다. 

작게는 회사나 공동체 그리고 가족 안에서도 잘못된 내용으로 상대를 얼마든지 힘들게 할 수 있음을 생각하게 된다. 

나 역시도 잘못된 정보를 퍼뜨리는 죄를 짓지 않도록 늘 조심해야겠다. 대신 기쁜 소식을 전파하는 데 힘을 사용해야겠다.

9. 적용
오늘은 김재현 간사님과 이른 아침에 한강대교 전도를 갔다. 
날씨도 너무 좋았고 준비된 영혼도 만나 전도지를 나누었다. 

그 전도지를 받은 영혼들이 예수님의 사랑을 알고 천국 무리가 될 수 있도록 간절히 기도해야겠다.

10. 영적터치 (단어 또는 구절)
9절: 아무 말도 대답하지 아니하시니 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-16', '누가복음', '23장 11~20절', '&nbsp;', '(누가복음 23장)
11. 헤롯이 그 군인들과 함께 예수를 업신여기며 희롱하고 빛난 옷을 입혀 빌라도에게 도로 보내니
12. 헤롯과 빌라도가 전에는 원수였으나 당일에 서로 친구가 되니라
13.  빌라도가 대제사장들과 관리들과 백성을 불러 모으고
14. 이르되 너희가 이 사람이 백성을 미혹하는 자라 하여 내게 끌고 왔도다 보라 내가 너희 앞에서 심문하였으되 너희가 고발하는 일에 대하여 이 사람에게서 죄를 찾지 못하였고
15. 헤롯이 또한 그렇게 하여 그를 우리에게 도로 보내었도다 보라 그가 행한 일에는 죽일 일이 없느니라
16. 그러므로 때려서 놓겠노라
17. (없음)
18. 무리가 일제히 소리 질러 이르되 이 사람을 없이하고 바라바를 우리에게 놓아 주소서 하니
19. 이 바라바는 성중에서 일어난 민란과 살인으로 말미암아 옥에 갇힌 자러라
20. 빌라도는 예수를 놓고자 하여 다시 그들에게 말하되

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2025년 8월17일 
누가복음 23장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
헤롯: 11절 12절
빌라도: 11절 12절 13절 20절
백성: 13절 14절
죄를 찾지못하였고/죽일 일이 없느니라: 14절 15절
바라바: 18절 19절
끌고/심문/고발: 14절 

4.주제 만들기: 
빌라도에게 예수를 고발하는 백성.

5.하나님 찾기 (관찰)
헤롯과 그 군인들에게 희롱당하시는 예수.
빌라도에게 다시 보내진 예수.
 
6.인간 찾기(관찰)
예수를 희롱하는 헤롯과 그 군인들.
대제사장들과 관리들과 백성을 불러 모으는 빌라도.
예수의 죄를 찾지못하는 빌라도.
예수를 심판할것을 더욱 크게 외치는 백성.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
 기독교 역사에 예수를 죽인 인물로 기록된 빌라도는 처음부터 예수를 죽이려고 하지는 않은 듯하다. 

다만 그는 유대인 무리를 두려워하였다. 사실 유대인들을 통치하는 로마의 총독이 강력하게 자신의 주관적 기준대로 예수를 풀어놓을 수 있는 위치였다. 

그런데도 자기 생각대로 하지 못하고 어정쩡하게 마음을 쉽게 정하지 못하였다. 

이유는 유대인들을 쉽게 통치하려면 민란이 일어나지 않도록 어느 정도 달래야 했기 때문이다. 

빌라도는 또한 예수라는 사람이 보통 사람이 아닌 비범한 인물이라 생각하고 있었던 것 같다. 

혹시나 자신과 가족이 피해를 볼까 두려워하는 마음도 있는 것 같다. 

그것은 믿음이 아닌 샤머니즘 같은 미신적 접근이었을 것 같다. 그래서 풀어주려고 했지만, 민란을 두려워하여 헤롯에게 보냈는데 다시 돌아온 예수를 적당히 때려서 풀어주려 했던 것 같다. 

그러한 절체절명의 상황에서 유대인 무리는 일제히 예수를 체포하라 외치고 있다. 심지어는 당시 살인죄로 감옥에 있는 바라바를 예수 대신 풀어주라고 요청하면서까지 외치고 있다. 

이렇게 예수를 십자가 죽음으로 가게 된 것은 인류를 구원하시고자 하는 크신 계획이 있어서 가능했지만 그렇다고 빌라도가 자신의 큰 죄(예수를 죽인)에서 자유롭지는 못할 것이다. 

만약 당시 빌라도가 확실히 미신이 아닌 믿음으로 예수를 만났다면 묻지도 않고 예수를 풀어주었을 것이다. 

그러면 빌라도는 영적인 역적이 아닌 다윗 같은 의인의 대열에 이름이 올라가 있지 않았을까 생각해 본다.

그리므로 예수를 평상시 경외하므로 주술적 대상이 아닌 하나님의 아들이요 주님으로 믿고 따른다는 것은 한 역사를 바꿀 수 있을 정도로 중요한 일인 것 같다

9. 적용
오늘은 주일이다. 주인되신 하나님을 더욱 사랑하고 믿음으로 찬양해야겠다.

10. 영적터치 (단어 또는 구절)
18절: 이 사람을 없이하고 바라바를 우리에게 놓아 주소서

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-17', '누가복음', '23장 21~30절', '가슴을 치며 슬피우는 여자들', '[눅23:21-30]
21 그들은 소리 질러 이르되 그를 십자가에 못 박게 하소서 십자가에 못 박게 하소서 하는지라
22 빌라도가 세 번째 말하되 이 사람이 무슨 악한 일을 하였느냐 나는 그에게서 죽일 죄를 찾지 못하였나니 때려서 놓으리라 하니
23 그들이 큰 소리로 재촉하여 십자가에 못 박기를 구하니 그들의 소리가 이긴지라
24 이에 빌라도가 그들이 구하는 대로 하기를 언도하고
25 그들이 요구하는 자 곧 민란과 살인으로 말미암아 옥에 갇힌 자를 놓아 주고 예수는 넘겨 주어 그들의 뜻대로 하게 하니라
26 그들이 예수를 끌고 갈 때에 시몬이라는 구레네 사람이 시골에서 오는 것을 붙들어 그에게 십자가를 지워 예수를 따르게 하더라
27 또 백성과 및 그를 위하여 가슴을 치며 슬피 우는 여자의 큰 무리가 따라오는지라
28 예수께서 돌이켜 그들을 향하여 이르시되 예루살렘의 딸들아 나를 위하여 울지 말고 너희와 너희 자녀를 위하여 울라
29 보라 날이 이르면 사람이 말하기를 잉태하지 못하는 이와 해산하지 못한 배와 먹이지 못한 젖이 복이 있다 하리라
30 그 때에 사람이 산들을 대하여 우리 위에 무너지라 하며 작은 산들을 대하여 우리를 덮으라 하리라

