1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 십자가에 못 박게 하소서(21,23절)
- 구하다(23,24절)
- 그들(21,23,25,26,28절)
- 빌라도(22,24절)
- 예수(25,26,28절)

4. 주제만들기: 가슴을 치며 슬피우는 여자들

5. 하나님 찾기 (관찰)
- 십자가를 지고 가시는 예수님
- 가슴을 치며 슬피우는 여자들에게 나를 위하여 울지 말고 너희와 너희 자손을 위해 울라 말씀하시는 예수님

6. 인간 찾기 (관찰)
- 빌라도는 세 번이나 무슨 악한 일을 했느냐 물었지만 십자가에 못 박으라 말하는 군중들
- 바라바를 놓아주고 예수님은 군중의 뜻대로 십자가에 못 박으라고 한 빌라도
- 구레네 사람 시몬에게 예수님의 십자가를 함께 지고 가게 함
- 예수님을 보고 가슴을 치며 슬피우는 여자들 

7. 하나님 찾기 (해석) 
- 하나님의 입장에서 민란과 살인을 한 바라바를 놓아달라고 요청하는 군중들의 모습이 얼마나 가슴이 아프셨을까?
- 인간을 만든 창조주이지만 인간의 죄를 위해 십자가를 지어야 하는 예수님의 선택과 사명에 가슴이 먹먹해진다.
- 예수님은 자신을 위해 우는 여인들을 향해 오히려 너희와 너희 자손을 위해 울라고 말씀하신다. 그것은 예수님을 믿지 못한 자들이 받을 심판을 말씀하신 것이다. 
- 예수님께선 우리의 죄를 사하기 위해 십자가를 지셨다. 우리를 구원하시기 위함이다. 
- 이와 더불어 공의 하나님이심을 기억해야 한다. 우리의 삶의 끝은 하나님의 심판이 함께 있다.
- 그것을 기억하며 이 땅에서의 삶을 소중히 감당해야겠다.

8. 인간(해석):
- 대중은 예수님을 십자가에 못 박으라 요구하고 있다. 그 안에는 대제사장과 서기관들이 중심에 있다. 
- 그들은 예수님을 십자가에 못 박고, 심각한 죄를 범한 바라바를 놓아주라 요구했다.
- 무엇이 그들의 눈을 가리우게 되었을까? 이 세상에서 놓지 못한 탐욕이 진리를 보는 눈을 가리웠을 것이다. 
- 나도 대제사장과 서기관처럼 예수님을 바로 바라보지 못할까 겁이 난다. 
- 예수님의 십자가를 보며 가슴을 치며 우는 여자들이 있다. 
- 예수님과 함께한 제자들은 어디에 있는지 알 수 없다. 예수님을 인간적인 마음에 동정하고 끝까지 자리를 지킨 의리가 대단하다 느껴진다.

9. 적용(나): 
- 하나님의 크신 사랑을 알게 하심에 감사드리며, 나에게 주어진 소명을 잘 감당할 수 있도록 더욱 노력해야겠다.

10. 영적터치(단어/구절)
- 예수께서 돌이켜 그들을 향하여 이르시되 예루살렘의 딸들아 나를 위하여 울지 말고 너희와 너희 자녀를 위하여 울라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-18', '누가복음', '23장 31~40절', '십자가 위에서도 사랑하시다', '누가복음 23장
31   푸른 나무에도 이같이 하거든 마른 나무에는 어떻게 되리요 하시니라
32   또 다른 두 행악자도 사형을 받게 되어 예수와 함께 끌려 가니라
33   해골이라 하는 곳에 이르러 거기서 예수를 십자가에 못 박고 두 행악자도 그렇게 하니 하나는 우편에, 하나는 좌편에 있더라
34   이에 예수께서 이르시되 아버지 저들을 사하여 주옵소서 자기들이 하는 것을 알지 못함이니이다 하시더라 그들이 그의 옷을 나눠 제비 뽑을새
35   백성은 서서 구경하는데 관리들은 비웃어 이르되 저가 남을 구원하였으니 만일 하나님이 택하신 자 그리스도이면 자신도 구원할지어다 하고
36   군인들도 희롱하면서 나아와 신 포도주를 주며
37   이르되 네가 만일 유대인의 왕이면 네가 너를 구원하라 하더라
38   그의 위에 이는 유대인의 왕이라 쓴 패가 있더라
39   달린 행악자 중 하나는 비방하여 이르되 네가 그리스도가 아니냐 너와 우리를 구원하라 하되
40   하나는 그 사람을 꾸짖어 이르되 네가 동일한 정죄를 받고서도 하나님을 두려워하지 아니하느냐

