1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 무덤(1,2,9절)
- 여자들(1,5,10절)
- 두사람(4,5절)
- 기억하다(6,8절)
- 살아나다(6,7절)

4. 주제만들기: 부활하신 예수

5. 하나님 찾기 (관찰)
- 천사를 무덤으로 보내 여인들에게 예수님이 살아나심을 말씀하심

6. 인간 찾기 (관찰)
- 준비한 향품을 들고 무덤으로 향한 여인들
- 무덤에 예수님이 보이지 않자 근심하는 여인들
- 두사람을 보고 두려워하는 여인들
- 두사람의 말을 듣고 예수님이 하신 말씀을 기억하는 여인들
- 예수님의 부활을 사도와 다른 이들에게 전하는 여인들

7. 하나님 찾기 (해석) 
- 두 천사의 등장은 하나님의 때가 시작되었음을 선포하는 생각이 든다.
- 여인들은 슬픔에 빠져 예수님의 몸에 바를 향품을 준비했지만 두 천사는 살아계신 자를 왜 죽은자 가운데서 찾느냐고 말한다.
- 여인들은 예수님께서 하신 말씀을 떠올리는데 그 직후 죽어있던 영이 깨어, 살아있는 영이 되어 사도와 모든 이에게 이 사실을 전하는 놀라운 일이 시작된다.
- 인간을 위해 죽음을 선택할 수 밖에 없었던 예수님은 더 이상 슬픔과 아픔의 존재가 아니다. 부활을 통해 우리에게 새로운 소망과 희망, 능력을 주셨다. 

8. 인간(해석):
- 당시 시대에 연약한 존재였던 여자들은 예수님이 살아나셨음을 깨닫고 담대히 사도들과 모든 이에게 이 사실을 전한다.
- 불과 몇 분전까지만 해도 슬픔에 빠져있던 존재인데 부활의 사실을 깨닫자마자 기쁨과 담대함이 가득해졌다.
- 예수님의 부활은 특별한 능력이 있다. 
- 예수님의 부활을 믿는 우리에게 동일한 능력이 있다.
- 우리의 삶은 죽은 자의 예수님이 아닌 부활하신 예수님과 같은 삶이다.
- 매일 부활하신 예수님을 깨닫고 인식한다면 우리의 삶은 기쁨이 가득할 것이다.

9. 적용(나): 
- 현재 발생한 현상에 집중하지 말고 부활하신 예수님을 매일 생각하며 기쁨과 능력이 가득한 하루하루 살아가야겠다.
- 기쁨에 가득한 여인처럼 예수님을 기쁨으로 전하는 자가 되고 싶다.

10. 영적터치(단어/구절)
