2025년 8월23일 
누가복음 24장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
두 사도: 13절 15절 16절 17절 
부활 예수: 15절 17절 19절
이야기하더라/이야기하며: 14절 15절
알아보지 못하거늘/알지 못하느냐 16절 18절

4.주제 만들기: 
부활 예수를 알아보지 못하는 두제자.

5.하나님 찾기 (관찰)
엠마오로 가는 두 제자와 동행하시는 부활하신 예수.
자신을 알아보지 못하는 두 제자들에게 말씀 하시는 예수.
 
6.인간 찾기(관찰)
예수님의 다시  사심(부활)을 믿지않는 사도들.
무덤으로 달려가서 놀라는 베드로.
엠마오로 걸어가는 두 제자.
눈이 가리어져서 부활 예수를 알아보지 못함.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
엠마오로 가는 제자 두 명은 예수님이 가까이 동행함에도 그들은 예수를 알아보지 못했다. 

그들은 평소 존경하고 따랐던 예수를 잃은 슬픔에 빠져있었다. 

부활하신 예수는 그들에게 천국의 기쁜 소식을 전하려 했지만, 상황은 반대였다. 

그 제자 두 명이 예수를 알아보지 못한 이유는 분명하다. 원인은 그들의 눈이 가리어졌기 때문이라 기록되었다. 

그러면 그들이 눈이 가리어진 이유는 무엇일까? 사탄의 방해 공작 때문일까? 아니면 두려움이 커서 못 알아본 것일까?

아마 두 가지 이유가 다 해당할 것이라 여겨진다. 평상시에 주님은 우리의 삶 가운데 다가오셔서 동행하시기를 원하시지만 힘든 삶의 무게로 모든 문제의 해결자인 이미 곁에 계신 예수께 도움을 요청하지 아니하고 스스로 문제를 해결하다 더욱 좌절감에 빠진 사람들을 쉽게 본다. 

또한 예수로 인하여 기뻐할 상황임에도 예수 때문에 슬퍼하는 큰 착각 속에 살 수 있다. 

그럴 뿐만 아니라 그들은 사도요 제자들임에도 사람들에게 왜곡된 사실을 알릴 수도 있다. 

사실 누구나 이러한 실수를 할 수 있기에 동행하시는 예수를 찾기 위하여 영적으로 눈이 열린다는 것은 매우 중요한 일이다. 

혹시 나도 기뻐할 때 슬퍼하고 슬퍼할 때 기뻐하는 영적 오류는 하지 않나 더욱 점검해야겠다.

9. 적용
부활하신 예수를 더욱 인식하고 의지하며 늘 천국소망을 갖고 살아야겠다.

10. 영적터치 (단어 또는 구절)
16절: 그들이 눈이 가리어져서 그인 줄 알아보지 못하거늘

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-23', '누가복음', '24장 31~40절', '제자들에게 나타나신 예수님', '[눅24:31-40]
31 그들의 눈이 밝아져 그인 줄 알아 보더니 예수는 그들에게 보이지 아니하시는지라
32 그들이 서로 말하되 길에서 우리에게 말씀하시고 우리에게 성경을 풀어 주실 때에 우리 속에서 마음이 뜨겁지 아니하더냐 하고
33 곧 그 때로 일어나 예루살렘에 돌아가 보니 열한 제자 및 그들과 함께 한 자들이 모여 있어
34 말하기를 주께서 과연 살아나시고 시몬에게 보이셨다 하는지라
35 두 사람도 길에서 된 일과 예수께서 떡을 떼심으로 자기들에게 알려지신 것을 말하더라
36 이 말을 할 때에 예수께서 친히 그들 가운데 서서 이르시되 너희에게 평강이 있을지어다 하시니
37 그들이 놀라고 무서워하여 그 보는 것을 영으로 생각하는지라
38 예수께서 이르시되 어찌하여 두려워하며 어찌하여 마음에 의심이 일어나느냐
39 내 손과 발을 보고 나인 줄 알라 또 나를 만져 보라 영은 살과 뼈가 없으되 너희 보는 바와 같이 나는 있느니라
40 이 말씀을 하시고 손과 발을 보이시나

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 예수(31,35,38절)
- 영(37,39절)
- 손과 발(39,40절)
- 보다(39,40절)

4. 주제만들기: 제자들에게 나타나신 예수님

5. 하나님 찾기 (관찰)
- 제자들에게 나타나신 예수님
- 평강이 있으라 말씀하신 예수님
- 마음에 의심하지 말라고 하시며, 손과 발을 보이시는 예수님

6. 인간 찾기 (관찰)
- 예수님을 알아본 직후 예수님의 말씀과 성경 풀이 때 마음이 뜨거워진 것을 깨닫는 제자들
- 예수님이 살아나신 것과 시몬에게 나타나신 것과 두 사람이 길에서 예수님을 만난 것을 서로 이야기 함
- 실제 나타나신 예수님을 영으로 생각하며 두려워하는 제자들

7. 하나님 찾기 (해석) 
- 예수님은 제자들에게 나타나셔서 가려진 눈을 뜨게 하셨고, 
- 예수님에 대해 선지자 정도로 생각한 제자들을 깨닫게 하셨고, 
- 소문으로만 들었던 부활하신 예수님이 직접 나타나사 마음에 의심을 없애주셨다.

8. 인간(해석):
- 예수님의 십자가 사건 후 제자들은 낙심에 빠져있었다.
- 부활하신 예수님을 전하는 여인들의 말에도 제자들은 인간이 죽음에서 다시 살아난 것을 쉽게 믿지 못했다. 
- 십자가에 달리신 예수님을 메시아가 아닌 선지자 정도로 생각했음을 짐작할 수 있다.
- 그러나 부활하신 예수님은 친히 제자들에게 나타나 그분의 존재를 깨닫게 하셨다.
- 놀라운 것은 제자들이 모여 예수님의 부활을 이야기할 때에 시몬(베드로)에게 나타나셨다는 사실을 알 수 있다. 
- 우리가 아는 요한복음에서의 만남일 수도 있고, 다른 이야기일 수도 있다.
- 그게 무엇이든 중요한 사실은 예수님의 십자가 사건으로 인해 가장 낙심한 제자 베드로를 회복시키고자 예수님이 찾아가셨단 사실이다.
- 예수님의 특별한 사랑을 깨달을 수 있다.
- 이 특별한 사랑은 우리 모두에게 적용된다. 
- 나를 특별히 사랑하셔서 예수님을 믿을 수 있는 믿음을 주신 은혜에 감사드린다.

9. 적용(나): 
- 예수님과 같은 차원이 다른 사랑을 실천하는 자가 되어야겠다.
- 예수님의 일을 할 때에는 보다 많은 지혜가 내 안에 주어지길 소망한다.

10. 영적터치(단어/구절)
- 34 말하기를 주께서 과연 살아나시고 시몬에게 보이셨다 하는지라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-08-24', '누가복음', '24장 21~30절', '&nbsp;', '(누가복음 24장)
21. 우리는 이 사람이 이스라엘을 속량할 자라고 바랐노라 이뿐 아니라 이 일이 일어난 지가 사흘째요
22. 또한 우리 중에 어떤 여자들이 우리로 놀라게 하였으니 이는 그들이 새벽에 무덤에 갔다가
23. 그의 시체는 보지 못하고 와서 그가 살아나셨다 하는 천사들의 나타남을 보았다 함이라
24. 또 우리와 함께 한 자 중에 두어 사람이 무덤에 가 과연 여자들이 말한 바와 같음을 보았으나 예수는 보지 못하였느니라 하거늘
25. 이르시되 미련하고 선지자들이 말한 모든 것을 마음에 더디 믿는 자들이여
26. 그리스도가 이런 고난을 받고 자기의 영광에 들어가야 할 것이 아니냐 하시고
27. 이에 모세와 모든 선지자의 글로 시작하여 모든 성경에 쓴 바 자기에 관한 것을 자세히 설명하시니라
28. 그들이 가는 마을에 가까이 가매 예수는 더 가려 하는 것 같이 하시니
29. 그들이 강권하여 이르되 우리와 함께 유하사이다 때가 저물어가고 날이 이미 기울었나이다 하니 이에 그들과 함께 유하러 들어가시니라
30. 그들과 함께 음식 잡수실 때에 떡을 가지사 축사하시고 떼어 그들에게 주시니

