2025년 8월24일 
누가복음 24장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
두제자: 21절 22절 24절 28절 29절 30절
부활 예수: 24절 26절
함께: 29절 30절
유함: 29절 30절
성경/모세와 모든선지자의 글:27절
무덤: 22절 24절

4.주제 만들기: 
두 제자에게 말씀을 설명하시는 부활 예수.

5.하나님 찾기 (관찰)
책망하시는 예수.
힘께 하시는 예수.
 
6.인간 찾기(관찰)
예수와 함께하기를 원하는 두 제자.
예수와 함께 음식을 나누며 유하는 두 제자.

7.하나님 찾기(해석)
예수님은 무지한 두 제자에게 친절하게 성경을 자세히 설명하셨다. 

공생애 3년 동안 무엇보다 말씀 사역을 하신 예수님께서 부활하신 이후에도 말씀을 가르치시는 일을 하고 계신다. 

그만큼 성경 말씀이 얼마나 중요한 것인지 몸소 보여주신 사건이라 생각한다. 

이 시대에도 열악한 북한 지하교회 성도들은 성경을 구하기 어려운 손으로 직접 쓴 공책에 있는 말씀을 생명의 위협을 감수하고라도 읽는다는 정보를 들었을 때 마음이 매우 어려웠다. 

남한에는 웬만한 집마다 읽지 않고 방치된 성경이 흔하게 있다고 전해 들을 때 많이 남한교회가 많이 반성해야 할 부분이다. 나도 하나님 말씀을 더욱더 귀하게 여겨야겠다.

8. 인간 찾기(해석)
엠마오로 가는 길에 부활하신 예수를 만난 두 제자는 여전히 주님을 알아보지 못하였다. 

예수님을 만나기 전 그들은 다른 여자들로부터 예수의 부활 증언도 들었다. 어쩌면 그 여자들은 천사의 증언만으로 믿고 있는데 두 제자는 바로 앞에 살아계신 예수를 보고도 알지 못하였다.

 그러한 그들에게 예수님은 성경을 자세히 설명하여 주셨다. 예수님의 열두 제자들은 아니지만 사도이고 제자라고 기록된 것을 보면, 성경을 통한 믿음이 있지 않았을까 생각해볼 때 다소 아쉬운 부분이다. 

지금 시대에도 마찬가지로 교회에서 직분을 갖고 있지만 제대로 성경에 대한 해석과 이해를 모른 체 예배만 참석하는 사람을 쉽게 본다. 

그런 면에서 우리 남북 청년 연합선교에서 매일 시행하는 3331 생명 큐티는 정말 매우 귀하고 소중한 시간이라 생각해본다.

9. 적용
더욱 하나님 말씀을 사랑해야겠다. 그리고 믿음으로 묵상해야겠다.

10. 영적터치 (단어 또는 구절)
26절: 영광에 들어가야 할 것

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

