누가복음의 저자인 의사 누가는 사도행전도 기록하였다.

누가복음을 전편이라 하면 사도행전을 후편이라 할 수 있겠다. 

누가는 예수님이 부활하신 과정을 제삼자 관점에서 다시 한번 언급하였다. 누가복음 24장에 예수님이 엠마오로 가는 두 제자에게 스스로 증언하며 특별히 ''고난''의 과정을 언급하기도 하셨다. 

그 말씀을 다시 되새기기라도 하듯 누가 역시 ''고난''이라는 단어를 사용하였다. 

누가는 부활하신 예수를 이제는 믿는 것에 머무르지 않고 사명자의 자세에서 세상에 알리는 복음자의 자세로 비취어지고 있다. 

1장 8절에 명확하게 성령님의 감동을 받고 기록한 것을 알 수 있다. 사실 이러한 사명믄 주님을 주인으로 모시고 시는 모든 신앙인 이라면 행하여할 사랑의 숙명인 것과 같은 것이라 여겨진다. 

그런 면에 우리 남북청년연합 선교회에도 마지막 때에 성령의 권능으로 전 세계 복음화에 앞장서는 그러한 사명자들이 많이 배출되기를 기대한다.

9. 적용
예수의 부활복음을 더욱 전파하는데 힘써야겠다.

10. 영적터치 (단어 또는 구절)
8절: 오직 성령이 너희에게 임하시면 너희가 권능을 받고 예루살렘과 온 유대와 사마리아와 땅 끝까지 이르러 내 증인이 되리라 하시니라.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

