8.인간 찾기(해석)
- 예수님의 승천을 본 제자들이 황홀한 가운데 멍하니 있다가,
- 예수님이 다시 오실 것이라는 천사의 말을 듣고 예수님이 다시 오실 날을 기대하게 되었을 것이다.

- 복음서에서 기도하는 모습을 거의 보이지 않던 제자들이 부활하신 예수님의 명령대로,
- 오로지 기도에 힘썼다.
