- 부활하신 예수님을 직접 본 제자들은 이제 예수님의 명령에 목숨을 거는 자들로 변화되었다.
- 또한 제자들이 이렇게 필사적으로 기도할 수 있었던 것은,
- 아마도 겟세마네 동산에서 피, 땀, 눈물을 흘려가며 기도하시던 예수님을 본받은 것으로 볼 수도 있을 것이다.

- 베드로는 말씀을 근거로 가룟 유다에 대해 설교하기 시작했다.

