8. 인간(해석):
- 예수님이 하늘로 승천하신 후 제자들은, 비로소 사역과 사명을 감당하기 시작하였다.
- 과거 예수님이 십자가에 매달리신 후 영적으로 침체되어 있던 모습이 아닌, 부활하신 예수님을 경험한 제자들은, 복음에 대한 확신으로 무슨 일이든 기도로 하나님의 뜻을 구하고 사역을 실행했다.
- 우리의 삶도 제자들의 모습처럼 사소한 것 하나까지 기도로 하나님의 뜻을 묻고 실행하는 것이 중요함을 다시 깨닫게 된다.
- 기도를 통해 제비를 뽑은 제자들은 맛디아를 사도로 세웠고,
- 사도의 직무 앞에 봉사가 먼저 있는 것으로 보아 사도의 직무를 수행하는 능력 이전에 봉사할 수 있는 성품이 중요하다는 것을 알 수 있다.
- 이 말은 사도의 직무를 수행하는 능력보다 하나님의 사랑을 실천할 수 있는 마음이 더 우선되어야 함을 생각해보게 되는데, 
- 과연 나는 하나님의 사랑을 실천하는 마음이 먼저인지, 사역으로 드러나는 성과를 우선 시 하는지 고민해본다.

9. 적용(나): 
- 봉사할 수 있는 마음이 내 안에 가득할 수 있도록 예수님께서 내게 보여주신 사랑을 다시 생각하고, 느끼고, 감사할 수 있는 첫사랑이 회복되길 간절히 기도해야겠다.
- 사역보다 봉사가 우선이라는 것을 잊지 말고 실천해야겠다.

