4. 주제만들기

5. 하나님 찾기 (관찰)
- 예수님을 다시 살린 하나님
- 다윗의 자손 중 한 사람을 왕위에 앉히겠다고 말씀하심

6. 인간 찾기 (관찰)
- 법 없는 자들이 예수님을 십자가에 못 박음
- 다윗은 항상 주를 바라보았음

7. 하나님 찾기 (해석) 
- 하나님은 태초부터 인간을 위해 자신이 직접 인간의 몸으로 이 땅에 내려와 십자가 지실 것을 결정하셨다. 
- 십자가를 지신 후 사흘만에 다시 살아나신 예수님으로 인해 우리는 사망에 매여 있지 않게 되었다.
- 우리는 하나님 사랑과 은혜를 잊지 말아야한다. 

8. 인간(해석):
- 오늘 본문에는 두가지 유형의 사람이 나온다. 
- 첫 번째는 법 없는 자들이다. 이들은 예수님을 십자가에 못 박는 어리석은 선택을 저질렀다.
- 두 번째는 다윗이다. 다윗은 항상 주님을 바라보았고, 흔들리지 않기를 바랬다.
- 삶을 살아가다보면 하나님이 말하시는 삶을 살아가기 힘들 때가 참 많다. 그럴 때 다윗과 같이 항상 하나님을 바라보고 흔들리는 생각에 넘어가지 않도록 하나님의 보호하심을 구해야 한다.
- 우리가 하나님으로부터 멀어져 있을수록 유혹에 넘어지기 쉽다. 예수님을 십자가에 매단 자들도 하나님과의 관계가 멀어져있었을 것이다. 
- 하나님과 친밀한 관계를 유지하는 것이 우리의 삶에 매우 중요한 요소이다.

9. 적용(나): 
- 하나님을 바라는 삶을 살아가길 구해야겠다. 
- 하나님의 뜻 가운데 믿음이 흔들리지 않도록 성령님의 보호하심을 구해야겠다.

10. 영적터치(단어/구절)
- 나로 요동하지 않게 하기 위하여

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

