4.주제 만들기: 
베드로의 오순절 외침.

5.하나님 찾기 (관찰)
마지막때를 예비하신 하나님.
 
6.인간 찾기(관찰)
오순절에 열한 사도와 함께 서서 소리를 내는 베드로.
하나님 말씀(선자자 요엘)을 인용하며 설교하는 베드로.

7.하나님 찾기(해석)
성령 하나님은 죄의 좌절 속에 있었던 베드로를 다시 일으키시고 설교자로 세우셨다. 

성령 하나님은 자신을 의지하는 모든 사람, 혹 죄인이라고 하더라도 다시 기회를 주시고 좋은 길로 인도하시는 선한 분이시다.

8. 인간 찾기(해석)
베드로는 다시 상남자로 돌아왔다. 아니 그가 예수를 배신하기 전보다 더욱 용감한 모습이 되었다. 

불과 얼마 전만 해도 그는 도망자요 배신자요 실패자였었다. 

무엇이 그를 변화시켰을까? 

그것은 성령 하나님의 역사하심 때문이다. 성령님이 우리 마음에 내재하신다면 우리로 과거의 죄를 회개케 하시고 주님의 자녀로서 담대한 사명자의 길을 걷도록 도와주시는 일을 하심을 베드로를 통해 발견한다.

또 하나는 평상시 말씀 묵상이나 훈련에 대한 중요함을 깨우친다. 

베드로는 많은 사람 앞에서 외칠 때 선지서 요엘을 인용하며 마지막 때의 모습을 표현하는 것을 알 수 있다. 

고기잡이 출신인 베드로가 하나님 말씀을 익히고 배울 때는 예수님과 함께했던 때인 것으로 추정한다면 평상시 말씀 훈련이 필요할 때 사용되는 것을 발견한다. 

말씀을 붙잡고 묵상하는 문제는 믿음이 강하나 약하든지 적용됨을 보여준다.

9. 적용
매 순간 성령 하나님을 더욱 의지하며 바른길로 가도록 최선을 다해야겠다.

10. 영적터치 (단어 또는 구절)
17절: 하나님이 말씀하시기를 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

