4.주제 만들기: 베드로의 설교 

5.하나님 찾기(관찰)
- 하나님이 예수님을 살리시고 높이심
- 예수님이 하나님께 성령을 받았고 그것을 제자들에게 부어 주심.

6.인간 찾기(관찰)
- 다윗이 미리 본 바와 같이 예수님이 죽지 않고 부활하심
- 예수님이 살아나신 일에 증인이 되는 제자들
- 우리가 어쩌면 좋겠느냐 묻는 이스라엘 백성들
- 대답하는 베드로

7.하나님 찾기(해석)
- 약속에 따라 십자가에 달리시고, 부활, 승천하시어 신자들에게 성령님을 부어 주심.
- 인간이 할 수 없는 것을 하나님께서 직접 행하시고 이루신 것.
 
8.인간 찾기(해석)
- 신자의 구원자가 오실 것과 그가 죽고 다시 살아날 것을 다윗은 미리 보고 알고 있었다.
- 예수님이 살아나신 일에 증인 됨을 선포하는 베드로
- 베드로의 설교와 증언에 성령의 감동으로 가슴이 찔려 우리가 어쩌면 좋겠느냐 묻는 이스라엘 백성들
- 이 날 이 장소에서 강림하신 성령님이 이들에게 역사하셨음이 명확하다.
- 이스라엘 백성들에게 회개하여 침례를 받고 죄 사함을 받으라고 대답하는 베드로
- 그리하면 성령을 받으리라 대답하는 베드로
- 성령님을 받기 위해서는 회개해야만 한다. 
- 예수님을 배제한 삶에서 예수님을 주님으로 모시는 삶으로 변해야 한다.
- 예수님을 주님으로 모시고 침례를 받고 죄 사함을 받아야 한다.
- 그리하면 성령의 선물을 받는다.
- 이것은 하나님의 약속이다. 

9.적용(나) 
- 약속하시고 선물을 주신 하나님께, 신자의 대주재 되시는 예수님께 감사와 찬양을 드려야겠다.
- 믿지 않는 자들이 가슴에 찔림을 받고 어찌하면 좋겠느냐 물을 때 베드로와 같이 대답할 줄 알아야 한다.

10.영적 터치(단어/구절)
