2025년 9월3일 
사도행전 2장41절~47절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
사도: 42절 43절 
함께/같이하여: 44절 46절
더하더라/더하게: 41절 47절
날마다: 46절 47절
힘쓰니라/힘쓰고: 42절 46절

4.주제 만들기: 
최초의 교회 그리고 부흥.

5.하나님 찾기 (관찰)
부흥케하시는 성령하나님.
기적과 표적을 허락하시는 하나님.
 
6.인간 찾기(관찰)
가르치는 사도.
교제와 떡을 떼며 기도에 힘쓰는 사람들.
구제활동 하는 사람들.

7.하나님 찾기(해석)
모든 부흥의 중심은 성령 하나님의 도우심이다. 

사도들이 말씀의 권위가 세워지는 것도 다 하나님 은혜요 기사와 표적을 일으키는 것도 마찬가지다. 

구원받는 사람을 날마다 더하시게 하시는 분도 하나님이시다.
오늘도 전능하신 하나님을 찬양하는 백성이 넘치기를 바란다!

8. 인간 찾기(해석)
인류의 최초 교회의 모습을 본다. 사도는 영적 권위가 있고 성도들은 말씀과 친교 그리고 기도를 열심히 하고 성전에 모이기를 힘쓴다. 

그럴 뿐만 아니라 어려운 이웃을 돕는 풍경이다. 신학교에서 배운 교회의 기능이 고스란히 배열되어 있다. 

다시 정리하면 예배와 말씀 그리고 기도와 교제 그리고 구제가 있다. 그들의 살을 통하여 자연스럽게 부흥이 이루어진다. 

하나님은 이들을 전 세계 디아스포라를 통하여 세계선교의 주역이 되게 사용하신다. 

나도 하나님의 은혜로 미국에서 2000년도에 비슷한 은혜는 교회공동체를 통하여 맛보았다. 

그 은혜가 너무 커서 그때 30살 절은 나이에 주님께 헌신하게 되었다. 지금 생각하면 이미 2000년 전에 성령 운동의 시작된 것을 본다. 

하나님의 교회와 선교를 향한 세게 복음화의 큰 물줄기에 한 방울의 쓰임을 받는다고 생각하니 감사가 나온다.

9. 적용
오늘 기도모임때 성령하나님을 더욱의지하여 기도에 힘써야겠다.

10. 영적터치 (단어 또는 구절)
42절: 오로지 기도하기를 힘쓰니라.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-09-03', '사도행전', '3장 11~20절', '겸손하고 담대히 예수님을 선포하는 베드로', '[행3:11-20]
11 나은 사람이 베드로와 요한을 붙잡으니 모든 백성이 크게 놀라며 달려 나아가 솔로몬의 행각이라 불리우는 행각에 모이거늘
12 베드로가 이것을 보고 백성에게 말하되 이스라엘 사람들아 이 일을 왜 놀랍게 여기느냐 우리 개인의 권능과 경건으로 이 사람을 걷게 한 것처럼 왜 우리를 주목하느냐
13 아브라함과 이삭과 야곱의 하나님 곧 우리 조상의 하나님이 그의 종 예수를 영화롭게 하셨느니라 너희가 그를 넘겨 주고 빌라도가 놓아 주기로 결의한 것을 너희가 그 앞에서 거부하였으니
14 너희가 거룩하고 의로운 이를 거부하고 도리어 살인한 사람을 놓아 주기를 구하여
15 생명의 주를 죽였도다 그러나 하나님이 죽은 자 가운데서 그를 살리셨으니 우리가 이 일에 증인이라
16 그 이름을 믿으므로 그 이름이 너희가 보고 아는 이 사람을 성하게 하였나니 예수로 말미암아 난 믿음이 너희 모든 사람 앞에서 이같이 완전히 낫게 하였느니라
17 형제들아 너희가 알지 못하여서 그리하였으며 너희 관리들도 그리한 줄 아노라
18 그러나 하나님이 모든 선지자의 입을 통하여 자기의 그리스도께서 고난 받으실 일을 미리 알게 하신 것을 이와 같이 이루셨느니라
19 그러므로 너희가 회개하고 돌이켜 너희 죄 없이 함을 받으라 이같이 하면 새롭게 되는 날이 주 앞으로부터 이를 것이요
20 또 주께서 너희를 위하여 예정하신 그리스도 곧 예수를 보내시리니

