5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 담대히 예수님을 전하는 베드로
- 예수님의 이름으로 나음을 받았다고 선포하는 베드로
- 회개하고 돌이켜 예수님을 믿으라 말하는 베드로

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 나면서부터 못 걷게 된 사람이 걷게 되자 많은 사람들이 놀랐다. 아마 베드로를 우러러 보았을 것이다.
- 그러나 베드로는 정확히 말한다. 개인의 권능과 경건의 능력이 아니니 우리를 주목하지 말라
- 예수님을 부인했던 베드로는 완전히 달라졌다. 담대히 말씀을 선포하면서 자신을 바라보는 이들에게 겸손함을 보인다. 이는 매우 중요한 부분이다. 
- 우리는 어떤 이유에서든 높임을 받을 때 넘어질 수 있다. 그러나 예수님의 모습을 가까이에서 본 제자들은 예수님의 십자가 사건 후 높임을 받는 것이 아니라 낮아지고 겸손해야 함을 깨달았을 것이다.

- 베드로는 예수님을 담대히 선포했다. 그의 말에는 아브라함부터 시작된 언약의 성취가 이루어졌음과 너희들이 몰랐기 때문에 예수를 버렸을 것이라 말하며, 
- 정죄보다는 깨닫고 뉘우칠 수 있도록 말하였다. 
- 회개를 권면할 때 강하고 부드러운 언어를 사용해야 됨을 깨닫는다. 

9. 적용(나): 
- 어느 자리에서든 겸손한 자가 되길 소망한다. 높아지고 싶은 마음을 성령님으로 인해 낮아질 수 있는 은혜가 있길 소망한다.
- 이웃을 사랑하는 마음이 내 안에 가득 임해지길 소망한다.

10. 영적터치(단어/구절)
- 우리 개인의 권능과 경건으로 이 사람을 걷게 한 것처럼 왜 우리를 주목하느냐

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

