5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 베드로와 요한이 오후 3시에 기도하러 성전에 올라감
- 사람들이 못 걷는 이를 메고 와서 성전 미문에 둠
- 못 걷는 이가 베드로와 요한에게 구걸함
- 베드로가 나사렛 예수 그리스도의 이름으로 일어나 걸으라 명령함
- 못 걷는 이나 일어나 걷기도 하고 뛰기도 하며 하나님을 찬송함
- 이를 본 모든 백성이 놀람

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 베드로와 요한이 기도하러 성전에 올라가다가 못 걷는 이를 만나게 되었다.
- 매일 모여 기도하던 베드로와 요한이 성령 충만을 받았고, 성령 충만을 받고 나서도 계속하여 힘써 기도하였다.
- 이 날도 기도하러 가는 길에 못 걷게 된 자를 만났고,
- 나사렛 예수 그리스도의 이름으로 그를 일으켰다.
- 우리는 기도하는 삶을 살아야 한다.

- 못 걷는 자가 구걸하였을 때 베드로와 요한은 그를 주목하여 보았다.
- 성경에 쓰여 있지는 않지만, 베드로와 요한이 그를 바라보고 있을 때 성령님께서 감동을 주셨을 것이다.
- 못 걷는 이는 돈을 받을 수 있겠구나 기대했지만,
- 베드로는 돈보다 더욱 값진 것을 예수님의 이름으로 주었고, 못 걷던 이는 베드로와 함께 성전으로 걷고 뛰며 하나님을 찬송하였다.
- 그는 이 일이 하나님의 역사임을 즉시 깨달은 것이다. 

- 이를 본 모든 사람들은 놀라며 이 일을 놀랍게 생각했다.
- 그들은 예수님의 이름의 능력과 성령님의 역사를 듣고 보고 깨닫게 될 것이다.
 
9.적용(나) 
- 예수님께서 약속하신 성령을 받은 후에도 지속하여 힘써 기도한 베드로와 요한을 본받자.
- 성령 충만을 받은 후에 기도하지 않으면, 성령님이 내 안에서 소멸할 수 있음을 기억해야 한다.
- 이런 의미에서 기도하지 않는 사람은 어쩌면 기독교인이 아닐 수 있다.

- 내게도 베드로처럼 예수 그리스도가 있는가? 
- 힘써 기도하는 하나님의 사람이 되고 싶다.

