4.주제 만들기: 
나사렛 예수그리스도의 이름

5.하나님 찾기 (관찰)
부활하신 예수.
 
6.인간 찾기(관찰)
사도들을 감옥에 가둔 사두개인들.
풀려난 사도들.
사도들을 심문하는 대제사장들과 종교지도자들.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
베드로는 더 이상 과거 베드로의 모습이 아니었다. 

대제사장 안나스와 다른 종교 지도자들이 사도들을 심문할 때 그는 담대하게 나서서 부활의 주를 드러냈다. 

사두개인의 모함으로 감옥에서 나온 지 불과 며칠 후의 일이었다. 주를 드러내는 일은 사실 목숨 걸고 하는 일이라고 볼 수 있다. 

얼마 전 예수님이 잡혀가실 때 뜰 가운데서 예수를 부인했던 믿음이 약한 베드로의 모습을 더 이상 찾아볼 수 없었다. 

베드로가 이렇게 용감한 주의 종이 될 수 있는 것은 무엇 때문일까?

8절에 그 답을 발견할 수 있다. "성령 충만" 임이 드러난다. 

사역할 때 가장 중요한 것은 어떠한 경험이나 기술이 아닌 "성령 충만함"이 가장 중요한 덕목인 것이 확실하다. 

충만하지 않으면 세상의 관점으로 사건을 바라보니 쉽게 믿음이 흔들리고 시험에 빠지는 것을 알 수 있다. 

그런 까닭의 매사에 성령 충만함을 바라고 구하는 데 힘을 쓰는 것은 승리를 이미 예고한 신호임이 확실하다.

9. 적용
성령 충만함을 더욱 사모하며 간절히 구해야겠다.

10. 영적터치 (단어 또는 구절)
8절: 베드로가 성령이 충만하여

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

