1:감동받는 단어나 구절 찾기(영적터치)

2025년 9월6일 
사도행전 3장21절~26절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
하나님: 21절 22절 25절 26절
선지자들/선지자: 21절 22절 23절 24절 25절
복: 25절 26절
회복/세울 것/악함을 버리게: 21절 22절 26절

4.주제 만들기: 
다시 복을 주시는 하나님.

5.하나님 찾기 (관찰)
회복을 준비하신 하나님.
언약의 하나님.
종을 세워 복주시는 하나님.
 
6.인간 찾기(관찰)
설교하는 베드로.
악을 따르지 않고 하나님의 언약을 믿고 따르는 자는 복을 받을 것이다.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
베드로는 성령의 능력으로 복음의 핵심을 선포하고 있다. 

구약의 아브라함과 하나님이 맹세한 언약이나 사무엘을 통한 오실 예수그리스도는 모든 인류를 회복시키고 복을 주시고자 함이 분명하다. 

다만 기다리는 과정에서 얼마나 잘 견디는지가 큰 숙제인 듯하다. 

베드로는 주님의 말씀을 큰 소리로 말한다. 악에 빠지면 멸망하고 주님을 의지하면 결국 회복될 뿐만 아니라 복을 받을 것이라는 아주 단순한 진리이다. 

이런 것을 생각하면 행복을 추구하는 것은 가까운 데 있음을 인지한다. 

마음을 비우고 산책하며 감사하기, 또는 별하늘을 보며 전능하신 하나님께 찬양하는 일, 소소한 일상에서 복이 이루어짐을 깨우친다. 

아브라함 때는 오실 예수님을 기다렸고 베드로 때는 오신 예수님을 만났다면 지금 시대는 다시 오실 예수님을 기다리는 시대인 듯하다. 

마지막 온전한 축복의 때를 바라며 오늘도 세상의 유혹에 빠지지 않고 복의 근원이신 주님과 동행하며 그를 찬양하는 삶이야말로 가장 행복한 삶이 아닐까 생각한다.

9. 적용
반복되는 일상 가운데 늘 감사하며 다시오실 복의 근원이신 주님을 찬양하며 기다려야겠다.

10. 영적터치 (단어 또는 구절)
26절: 하나님이 그 종을 세워 복 주시려고 너희에게 먼저 보내사

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-09-07', '사도행전', '4장 11~20절', '보고 들은 것을 믿는 제자들, 보고 들은 것을 믿지 않는 사두개인과 성전 맡은 자들', '[행4:11-20]
11 이 예수는 너희 건축자들의 버린 돌로서 집 모퉁이의 머릿돌이 되었느니라
12 다른 이로써는 구원을 받을 수 없나니 천하 사람 중에 구원을 받을 만한 다른 이름을 우리에게 주신 일이 없음이라 하였더라
13 그들이 베드로와 요한이 담대하게 말함을 보고 그들을 본래 학문 없는 범인으로 알았다가 이상히 여기며 또 전에 예수와 함께 있던 줄도 알고
14 또 병 나은 사람이 그들과 함께 서 있는 것을 보고 비난할 말이 없는지라
15 명하여 공회에서 나가라 하고 서로 의논하여 이르되
16 이 사람들을 어떻게 할까 그들로 말미암아 유명한 표적 나타난 것이 예루살렘에 사는 모든 사람에게 알려졌으니 우리도 부인할 수 없는지라
17 이것이 민간에 더 퍼지지 못하게 그들을 위협하여 이 후에는 이 이름으로 아무에게도 말하지 말게 하자 하고
18 그들을 불러 경고하여 도무지 예수의 이름으로 말하지도 말고 가르치지도 말라 하니
19 베드로와 요한이 대답하여 이르되 하나님 앞에서 너희의 말을 듣는 것이 하나님의 말씀을 듣는 것보다 옳은가 판단하라
20 우리는 보고 들은 것을 말하지 아니할 수 없다 하니

