4. 주제만들기: 보고 들은 것을 믿는 제자들, 보고 들은 것을 믿지 않는 사두개인과 성전 맡은 자들

5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 공회에서 나가고 예수의 이름으로 말하지도 가르치지지도 말라 명하는 성전 맡은 자들과 사두개인들
- 하나님 앞에서 너희의 말보다 하나님의 말씀을 따르는 것이 옳다 말하는 베드로와 요한
- 보고 들은 것을 말하지 않을 수 없다는 베드로와 요한

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 성령의 능력은 대단하다. 예수님을 버리고 떠났던 제자들은 완전히 다른 사람이 되었다. 
- 과거 도망치는 존재였다면, 이제는 불의와 거짓된 진리에 맞서 위정자들 앞에서 담대히 예수님을 선포한다. 
- 성령의 능력은 이런 것이다. 우리도 성령의 능력으로 무엇이든 할 수 있다.
- 반면 성전 맡은 자들과 사두개인들은 이들의 말에 비난할 것이 없다는 것을 알면서도 예수님을 부정한다. 
- 어쩌면 예수님을 인정하지만 자신들의 안위가 걱정되어 자신의 것을 지키고자 예수님을 부정했을 수도 있다.
- 중요한 것은 누구에게나 주어진 복음이어도 복음을 받아들이는 것은 전적인 하나님의 은혜이다. 
- 지금 3331 생명의 큐티를 하고 있는 우리는 구원의 은혜를 받은 존재이다.
- 우리도 베드로와 요한처럼 담대히 복음을 전할 수 있어야 한다. 

9. 적용(나): 
- 3331 큐티가 아니었더라면, 남북청년연합 선교회가 아니었더라면, 전도조차 하지 않고 부끄러운 구원을 받았을 수 있다. 주님의 은혜에 감사해야겠다.
- 담대히 복음을 전해야겠다.

10. 영적터치(단어/구절)
- 비난할 말이 없는지라
- 우리는 보고 들은 것을 말하지 아니할 수 없다 하니

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

