4.주제 만들기: 하나님께 한 마음으로 기도하는 제자들

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 관리들이 베드로와 요한을 놓아줌
- 베드로와 요한이 제사장들과 장로들의 말을 제자들에게 전함
- 제자들이 한 마음으로 하나님께 기도함
 
7.하나님 찾기(해석)

8.인간 찾기(해석)
- 일어난 기적과 이 기적을 보고 하나님께 영광을 돌리는 백성들로 인해 관리들은 베드로와 요한을 놓아주었다.
- 하나님께서는 베드로와 요한을 위협에서 건져내실 뿐만 아니라 백성들에게 영광도 받으셨다.
- 이 일은 베드로와 요한에게 큰 기쁨이 되었다.

- 베드로와 요한은 제사장과 장로들에게 들은 이야기, 즉 복음을 전하면 가만 두지 않겠다는 그들의 위협에 대해 제자들에게 알렸다.
- 복음서의 제자들이라면 두려움을 느끼며 도피할 준비를 했을 터인데, 사도행전에서는 그러지 않고 한 마음으로 소리를 높여 기도하기 시작했다.

- 부활하신 예수님을 만나고 그 예수님께 성경과 하나님 나라에 대해 자세히 배우고 꺠달은 그들은, 예수님께서 이 땅에 오시어 백성들에게 고난받으신 것이 이미 정해진 것임을 알게 되었다.
- 헤롯과 본디오 빌라도, 당시의 대적자들이 하나님의 뜻으로 다 예정되어 있었고 모였음을 알게 되었다.

- 모든 것이 하나님의 뜻대로 이루어지는 것을 알게 된 제자들은 하나님의 도우심을 구하며 부르짖는다.
- 그 부르짖는 말은 보호하심과 복음 전도, 그리고 예수님의 이름으로 일어나는 표적과 기사이다.
- 기도의 내용이 모두 다 하나님의 영광을 위한 것이라는 것에 주목해야 한다.

9.적용(나) 
- 주님을 위하여 살다가 핍박을 받게 되면 괴롭다. 그러나 우리는 그 시간에 하나님께서 영광 받으시는 것을 기억하고 기뻐해야 한다.
- 베드로는 위협을 받아도 기뻐했으며, 죽기 직전까지 맞아도 주를 위해 고난받는 것을 기뻐하였다.
- 하나님 나라를 전하는 도구로 사용 받는 자 됨을 인정받는 것이므로 기뻐한 것이다.

- 성령 충만을 받아 하나님의 도구로 사용 됨에 기뻐하는 자가 되고 싶다. 나는 드러나지 않아도 된다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-09-09', '사도행전', '4장 31~37절', '&nbsp;', '(사도행전 4장)
31. 빌기를 다하매 모인 곳이 진동하더니 무리가 다 성령이 충만하여 담대히 하나님의 말씀을 전하니라
32.  믿는 무리가 한마음과 한 뜻이 되어 모든 물건을 서로 통용하고 자기 재물을 조금이라도 자기 것이라 하는 이가 하나도 없더라
33. 사도들이 큰 권능으로 주 예수의 부활을 증언하니 무리가 큰 은혜를 받아
34. 그 중에 가난한 사람이 없으니 이는 밭과 집 있는 자는 팔아 그 판 것의 값을 가져다가
35. 사도들의 발 앞에 두매 그들이 각 사람의 필요를 따라 나누어 줌이라
36. 구브로에서 난 레위족 사람이 있으니 이름은 요셉이라 사도들이 일컬어 바나바라(번역하면 위로의 아들이라) 하니
37. 그가 밭이 있으매 팔아 그 값을 가지고 사도들의 발 앞에 두니라

