6.인간 찾기(관찰)
- 아나니아와 삽비라가 소유를 팔아 그 값의 얼마를 감춤
- 아나니아가 그 값의 일부만 가져가 사도들 앞에 둠
- 베드로가 아나니아를 꾸짖음
- 사람이 아니라 하나님께 거짓말한 것이라 말하는 베드로
- 아나니아가 엎드러져 혼이 떠남
- 아나니아를 묻고 오는 젊은이들
- 세 시간 뒤 들어와 거짓말 하는 삽비라
- 삽비라를 꾸짖는 베드로
- 삽비라가 엎드러져 혼이 떠남
- 삽비라를 아나니아 곁에 장사함

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 어떤 의도가 있었는지 모르겠으나, 아나니아와 삽비라가 소유를 팔아 사도들 발 앞에 두고자 마음을 먹음
- 바나바가 성령에 감동되어 소유를 내놓은 것을 보고 허영심이 생긴 것일까,
- 아니면 정치적 의도가 있었던 것일까,
- 그것도 아니면 순수한 마음이었을까?
- 어찌 되었든 나도 소유를 팔아 사도들께 드리겠다 공언했을 것이다.
- 그러나 얼마를 숨겼고, 거짓말을 하였다.

- 성령 충만한 베드로는 아나니아의 거짓말을 알고 있었고,
- 이 거짓말은 사람이 아니라 하나님께 거짓말한 것이라고 꾸짖음.
- 그리고 아나니아는 혼이 떠남.

- 삽비라가 베드로의 질문에 거짓말을 하고 혼이 떠남

- 이 사람들이 소유를 팔아 사도들에게 드리는 행동은 참으로 훌륭한 일이다.
- 거짓말 하지 않았다면, 훌륭한 믿음의 사람들로 남았을 텐데, 왜 거짓말을 했을까?
- 어째서 거짓말까지 하면서까지 사도들 앞에 드렸을까?
- 허영심 때문일까, 바나바에 대한 시기심 때문이었을까, 정치적인 이유에서였을까?
- 알 수 없으나, 베드로의 말을 보면 아나니아의 마음에 사탄이 가득하였다고 했다.

- 또한 중요한 것은 하나님 앞에서 거짓된 행동을 한 아나니아와 삽비라가 죽었다는 것이다.
- 우리는 하나님 앞에서 정직해야 한다.
 
9.적용(나) 
- 아나니아와 삽비라는 제자들과 함께 하던 자들이다.
- 믿음의 공동체에 속해 있던 사람들이지만, 하나님을 속인 죄로 그 자리에서 죽었다.
- 이것은 오늘날 기독교인들이 깊이 생각해 봐야 하는 사건이다.
- 우리는 누군가를 속이지 말고, 순수하고 정직하게 살아야 한다.

