5.하나님 찾기 (관찰)
 그리스도 되신 예수.
 
6.인간 찾기(관찰)
사도들을 죽이려하는 종교지도자들.
중재를 하는 율법교사 가말리엘.
사도들을 능욕하고 채찍질한 후에 풀어준 종교지도자들.
풀어난 후에도 쉬지않고 복음을 가르치고 전도를 하는 사도들.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
사도들이 복음을 담대하게 전파할 때 크게 반감이 있는 종교 지도자들은 그들을 죽이려 하였다. 

그때 모든 백성에게 존경받는 율법 교사 가말리엘이 중재를 하였고 방침으로는 그냥 내버려 두라는 것이다. 

그 논리로는 이단이면 흩어질 것이고 하나님께 속한 사람들이면 무너뜨릴 수 없다는 것이다. 

생각해 보면 참 생명의 신앙인 기독교가 그때를 기준으로 2000년이 지난 현재를 생각하면 더욱 부흥됐다는 사실을 볼 수 있다. 

그런데도 여전히 많은 사람을 미혹하게 하는 많은 이단 종교는 없어질 것이라는 생각을 해본다. 설령 

그러한 사이비 집단이 오랫동안 유지된다고 하더라도 마지막 때 크게 심판받을 것은 자명한 진리이다.

한편 채찍을 맞은 후 풀려난 사도들은 날마다 성전이나 집에서 복음을 가르치고 전파하는데 열정이 식지 않았다. 

도리어 그들은 복음 전파로 능욕 받는 일을 기뻐했다고 기록되어 있다. 

이러한 모습을 보면 참된 주님 제자의 태도를 발견한다. 그들의 이러한 세상에서 감당하지 못하는 복음의 열정 덕분에 현 대한민국 안에 많은 기독교인이 생겨났음을 생각하면 사도들에게 감사한 생각이 든다. 

물론 중심에는 성령 하나님의 도우심이 있었기에 가능하다. 

사랑의 빚진 자로써 가정과 공동체 안에서 예수가 참 그리스도이신 것을 가르치고 나누는데 더욱 열심히 해야겠다.

9. 적용
