7.하나님 찾기(해석)

8.인간 찾기(해석)
- 성령 충만한 스데반을 말로 이기지 못한 자들이 스데반을 모함함
- 이 사람들은 하나님을 믿는다는 지식인들이었음
- 겉으로는 대단한 믿음의 사람들이지만, 속에는 악으로 가득 차 있으며 거짓으로 사람을 죽일 생각까지 하는 사람들임
- 자신들이 쌓아온 지식과 가치관이 무너질 때 사람은 짐승으로 변할 수 있음

- 그리스도인들은 먼저 스스로 겸비해야 하고,
- 믿음이 약한 자나 믿음이 없는 자에게 복음을 전할 때에는
 친절하고 차분하게 말할 필요가 있으며,
 그렇게 말할지라도 듣는 이들에게 나쁜 감정이 생길 수 있음을 알고 주의해야 한다.
- 복음은 사람을 감동시켜 구원에 이르게도 하지만,
거부하는 자들에게는 분노의 대상이 될 수 있기 때문이다.

9.적용(나) 
