- 죽음이 임박한 와중에 무릎을 꿇고 저들의 죄를 용서해달라고 기도하는 스데반

7. 하나님 찾기 (해석)
- 하나님은 스데반을 자랑스러워셨고, 그의 용기와 결단에 성령 충만함으로 하늘나라를 보게하셨다.

8. 인간(해석):
- 6장에서 예수를 전하는 스데반의 얼굴을 천사의 얼굴과 같다고 표현했다. 
- 누군가에겐 천사의 얼굴로 보였을 것이고, 누군가에게 제거해야 할 대상으로 보였다.
- 성령 충만은 잘못된 정보가 넘쳐나는 세상에서 진리를 바르게 바라볼 수 있는 증거가 된다.
- 스데반이 자신들의 잘못을 말했을 때 대제사장과 유대인들은 창피했을 것이다.
- 자신들의 잘못임을 알면서도, 자신들의 수치가 드러나는 것을 더 괴로워했다.
- 그것으로 인해 예수님을 죽였음에도 다시 동일한 죄를 짓게 된다.
- 육신의 정욕, 안목의 정욕, 이생의 자랑은 분명하다.
- 그것은 우리를 넘어뜨리고, 죄에서 벗어나지 못하게 하고, 예수님으로부터 멀어지게 한다.
- 성령 충만함이 우리에게 필요한 이유다.

9. 적용(나): 
- 예수님을 영과 진리로 예배하는 가정이 되도록 결단했다. 우리 가정이 예수님을 사랑하고, 예수님만 의지하는 가정되길 소망한다.

10. 영적터치(단어/구절)
- 스데반이 성령 충만하여

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

