6.인간 찾기(관찰)
우상(송아지)을 만든 무지한 백성들.
우상숭배의 죄를 짓고 쫓겨난 이스라엘 백성들.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
자기 손으로 만든 것 vs 하나님 손으로 지은 것이 대비됨을 보여준다. 

우상인 송아지를 만든 것에 대해 하나님은 단호하셨다. 

우상을 섬긴다는 것은 하나님과의 단절을 의미하며 더 나아가 대적한다는 사실이다.  

우상숭배의 근본정신은 스스로 높아지는 것을 알 수 있다. 이렇게 보면 세상에서 성공한 사람처럼 보일지라도 하나님과 관련이 없는 사람은 실패한 삶이라 확실시된다. 

그들의 마음에는 이미 하나님과 같아지는 마음 즉 교만한 마음이 이미 가득하여 있기 때문이다. 

마치 최초 인간인 아담과 하와가 선악과를 먹고 하나님처럼 되고자 했던 것과 유사하다. 

그런 면에서 하나님 앞에서 겸손함은  인간의 기본적 덕목을 넘어 우리의 생과 사를 결정 짓은 매우 중요한 일인 것은 분명하다. 

인간 스스로 만든 것이 아무리 위대하고 거대하더라도 우주 만물을 지으신 하나님의 크기 앞에서는 그저 조그마한 사라질 먼지 크기밖에 되지 않을 것은 분명한 진리이다.

9. 적용
모든 만물을 창조하시고 주인되신 하나님을 더욱 찬양하는 시간을 가져야겠다.

10. 영적터치 (단어 또는 구절)
