- 사람들이 짐승처럼 으르렁 거리며 스데반을 돌로 쳐 죽인 것을 마땅하게 생각했다.
- 사울도 그들과 같은 부류였다.
- 그래서 사울은 앞장서서 교회를 잔멸하고자 부지런히 움직였다.

- 위기의 순간에도 경건한 사람들은 용기를 내어 스데반을 장사하고 크게 울었다.

- 이 사건으로 인해 교회는 흩어졌으나, 흩어진 사람들이 각각 흩어진 곳에서 그리스도를 전하였다.
- 이 흩어짐은 도피가 아니라 거룩한 확장으로 보아야 할 것이다.

- 그 중 빌립 집사는 사마리아 성에 가서 그리스도를 전하였고, 그로 인하여 그 성에는 기쁨이 넘쳤다.
- 빌립 집사는 그리스도를 전할 뿐만 아니라 귀신을 내쫓고 병든 자를 고쳐주었다.
- 사마리아 성 사람들은 빌립의 말도 듣고 표적도 보고 그의 말을 따랐다.
 
