INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-09-23', '사도행전', '8장 11~20절', '&nbsp;', '(사도행전 8장)
11. 오랫동안 그 마술에 놀랐으므로 그들이 따르더니
