8. 인간(해석):
- 하나님의 타이밍은 완벽하시다, 내시가 이사야를 읽었을 때 풀리지 않던 의문을 빌립으로부터 듣게 되자 복음을 쉽게 받아들였다.
- 성경을 읽고 지적 호기심이 충분히 차올랐을 때 내시는 성령님의 인도하심으로 세례를 받게 된다.
- 각자에게 주어진 하나님의 타이밍은 다를 것이다. 분명한건 너무도 완벽하게, 드라마틱한 시점에 하나님께서 임하신다는 것이다.
- 어떠한 상황이든, 의문이든 간에, 하나님의 뜻이 있고, 하나님이 이루실 일들을 굳게 믿으며 이겨내야겠다.
- 하나님께서 이루신 내 삶에 내시와 같은 기쁨이 가득하길 소망한다.

9. 적용(나): 
- 하나님은 살아계시며, 하나님의 역사는 반드시 이루어진다. 성령충만함으로 하나님의 때를 기다려야겠다.
- 기쁜 마음으로 노방전도를 이어가야겠다.

