2025년 9월27일 
사도행전 9장 1절~10절
1.1분기도
2. 본문 성경 읽기(3번)
3. 반복 단어 찾기(형광펜 사용 추천):
사울: 1절 3절 4절(2) 6절(3) 8절
위협과 살기/결박/잡아 오려 함/박해: 1절 2절 5절
보지 못하(여)고: 7절 8절 9절
다메섹: 3절 8절 10절
아나니야: 10절(2)
주/예수: 4절 5절 10절(2)

4. 주제 만들기: 
예수를 박해하는 사울.

5. 하나님 찾기 (관찰)
 사울을 부르시는 예수.
아나니아가 있는 시내로 들어가라 지시하시는 예수.
 
6.인간 찾기(관찰)
주를 따르는 제자들을 잡으려 살기가 등등하는 사울.
다메섹으로 가는 길에 예수를 만난 사울.
눈이 어두워진 사울.

7. 하나님 찾기(해석)
하나님은 사도바울의 치부라고 생각할 수 있는 과거의 죄악 된 모습을 의도적으로 기록하셨다. 

왜 그렇게 하셨을까? 생각해 보면 사랑의 하나님이 사도바울을 괴롭게 하기 위한 목적으로 행하지 않음은 확실하다. 

다만 겸손과 은혜를 일깨워 주시고자 하는 의도가 있는 것 같다. 

훗날 사도바울이 유명한 사람이 됐을 때, 변함없이 주님의 은혜를 잊지 않고 더욱 하나님 안에서 섬기는 자가 되기를 원하심인 듯하다. 

믿는 신자들도 마찬가지로 문득 과거의 실수나 잘못한 행위가 떠오를 때 같은 해석으로 접근하면 될듯하다. 언제나 지켜주시고 성장케 해주시는 하나님께 찬양을 올립니다.

8. 인간 찾기(해석)
신약성경에서 등장하는 인물 중에 복음 전파에 가장 열정적이고 내면적으로 최고의 영성가 한 사람을 뽑는다면 누구나 대부분 사도바울을 생각할 것이다. 

그러한 위대한 업적을 남긴 사도바울한테도 부끄러운 과거가 있었다. 아마 훗날에 사도바울이 가장 부끄러워하는 때가 아닌가 생각해 본다. 

내용을 보면 그는 주님의 제자들을 잡고 대제사장에게 넘기기 위해 다메섹으로 갔다. 

그때 그의 눈빛은 살기가 등등하였다고 되어있다. 그러한 사울 청년에게 주님은 그의 눈을 가리는 표적을 보이시며 음성을 들려주셨다. 

사실 그 당시에 바울인 사울 청년은 주님 제자들의 행동을 하나님의 법을 거슬리는 이단으로 생각했던 것 같았다. 

그러므로 그는 자신이 도리어 하나님의 옳은 일을 한다고 착각하고 있었다. 

믿는 사람들도 잠시 영의 눈이 어두워져서 스스로 주님의 뜻이라고 확신하고 주변의 믿음이 약한 사람들을 쉽게 판단하거나 정죄할 수가 있는 오류를 범할 수 있음을 깨우친다.

9. 적용
영적으로 눈이 어두워지지 않도록 항상 깨워 기도해야겠다.

10. 영적 터치 (단어 또는 구절)
4절: 사울이 사울아 네가 어찌하여 나를 박해하느냐? 

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-09-27', '사도행전', '9장 11~20절', '&nbsp;', '(사도행전 9장)
11. 주께서 이르시되 일어나 직가라 하는 거리로 가서 유다의 집에서 다소 사람 사울이라 하는 사람을 찾으라 그가 기도하는 중이니라
12. 그가 아나니아라 하는 사람이 들어와서 자기에게 안수하여 다시 보게 하는 것을 보았느니라 하시거늘
13. 아나니아가 대답하되 주여 이 사람에 대하여 내가 여러 사람에게 듣사온즉 그가 예루살렘에서 주의 성도에게 적지 않은 해를 끼쳤다 하더니
14. 여기서도 주의 이름을 부르는 모든 사람을 결박할 권한을 대제사장들에게서 받았나이다 하거늘
15. 주께서 이르시되 가라 이 사람은 내 이름을 이방인과 임금들과 이스라엘 자손들에게 전하기 위하여 택한 나의 그릇이라
16. 그가 내 이름을 위하여 얼마나 고난을 받아야 할 것을 내가 그에게 보이리라 하시니
17. 아나니아가 떠나 그 집에 들어가서 그에게 안수하여 이르되 형제 사울아 주 곧 네가 오는 길에서 나타나셨던 예수께서 나를 보내어 너로 다시 보게 하시고 성령으로 충만하게 하신다 하니
18. 즉시 사울의 눈에서 비늘 같은 것이 벗어져 다시 보게 된지라 일어나 세례를 받고
19. 음식을 먹으매 강건하여지니라 사울이 다메섹에 있는 제자들과 함께 며칠 있을새
20. 즉시로 각 회당에서 예수가 하나님의 아들이심을 전파하니

