2025년 9월28일 
사도행전 9장 11절~20절
1.1분기도
2. 본문 성경 읽기(3번)
3. 반복 단어 찾기(형광펜 사용 추천):
주의 이름: 14절 15절 16절 
아나니아: 12절 13절 17절
사울: 11절 13절 16절 18절 19절
전함/전파: 15절 20절
보게 됨: 17절 18절 19절

4. 주제 만들기: 
결박자에서 복음 전파자로 변화된 사울.

5. 하나님 찾기 (관찰)
 아나니아에게 사울을 택하신 목적을 알려주시는 주님.
 
6.인간 찾기(관찰)
사울을 아직 믿지 못하는 아나니아.
결국 주님께 순종하고 사울에게 안수해준 아나니아.
그때 사울의 눈에서 비늘 같은 것이 벗겨져 다시 보게 됨.
즉시 복음을 전파하는 사울.

7. 하나님 찾기(해석)
사울 청년은 주의 제자인 아나니아가 소문을 들을 정도로 주의 이름을 부르는 자들을 결박하는 핍박자였다. 

그러한 사울이 주님의 은혜로 말미암아 주의 이름을 위하여 고난도 받고 이름을 전파하는 자가 되었다. 

아나니아의 기도로 영의 눈이 열린 그는 20절에 "즉시" 복음을 전파하는 자가 되었음을 알 수 있다. 주님은 사울이 잘못된 방향을 바로잡아주셨다. 

그랬더니 그의 원래 선천적 기질적인 뜨거운 열정이 즉각 복음을 선포하는 사람으로 인도하였다. 

사울 청년이 복음을 전파한다는 행위는 당시 종교 지도자들에게 대항하는 역적 같은 행동이라 죽임을 당할 수 있는 사실을 누구보다도 그는 알고 있었다. 

그는 스스로 가치 있는 일이라면 목숨도 거는 엄청난 열정을 가지고 있었음을 알 수 있다. 

그 열정은 세상에서만 통용되는 것이 아니라 하나님이 사람을 택할 시 때도 중요시 보시는 듯하다.

8. 인간 찾기(해석)
사람은 누구나 하나님 은혜로 변할 수 있음을 볼 수 있다. 

포악한 겹박자였던 사울이 이제는 사람을 살리는데 열심을 품는 사람으로 승화된 것을 보면 누구든지 과거보다 좋은 인격체로 변할 가능성이 있다는 사실이다. 

주변에 어떠한 사람이 과거에 실망스러운 행동이나 실수하였더라도 인생 전체를 안 좋은 잣대로 단정 지어서는 안 됨을 알게 된다. 

누구든지 좋은 하나님께 사울 청년처럼 쓰임 받을 수 있다는 가능성을 인지해야 함을 알게 된다. 그런 까닭에 복음 전파가 얼마나 귀한 일인지 더욱 알게 된다.

9. 적용
더욱 복음 전파에 힘써야겠다.

10. 영적 터치 (단어 또는 구절)
20절: 즉시로

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

