5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 룻다에 사는 성도들을 찾아가 베드로
- 8년째 중풍병으로 누워있던 애니아를 주님의 이름으로 일어킨 베드로
- 욥바의 제자들의 청으로 욥바로 간 베드로
- 이미 죽은 다비다를 기도로 살린 베드로
  
7.하나님 찾기(해석)

8.인간 찾기(해석)
- 하나님을 경외함과 성령의 위로는 교회를 튼튼하게 만든다.
- 우리 신자들은 하나님을 경외해야 한다. 그러면 성령님은 우리가 튼튼히 서도록 늘 도우신다.

- 베드로는 예수님의 명을 따라 다른 사람들의 믿음을 굳건하게 하기 위하여 사방을 두루 다녔다.
- 그러던 중 중풍병에 걸린 애니아를 만났고, 주님의 이름으로 일으켜 세웠다.
- 욥바에 있는 제자들의 요청으로 욥바로 내려간 베드로가 이미 죽은 다비다를 살림
- 욥바와 룻다의 거리는 약 20km로 베드로가 욥바로 갔을 때는 이미 많은 시간이 지난 후였을 것이다.
- 가면서도 기도했을 베드로가 다비다 앞에서 주님 앞에 무릎을 꿇고 기도를 한 후에 다비다를 살렸다.
- 신자는 늘 기도하되, 현장에서 또 기도해야 하며,
- 어려운 일이 있을 때 성령 충만한 사람에게 기도를 부탁해야 한다.

- 베드로를 통해 일어난 기적은 신자들의 믿음을 더욱 굳건하게 하고 하나님을 더욱 경외하게 만드는 사건이었다.
 
9.적용(나)
- 평소에 기도를 해왔거나, 아침에 기도한 내용이면, 현장에서 기도하지 않고 행할 때가 종종 있었다.
- 사람들 앞에서 행하는 외식이거나, 사람들이 불편할 수 있다고 생각해서였는데,
- 이것은 잘못된 것이라는 생각이 든다.

- 나의 기도는 하나님께 드리는 것이지 사람에게 보이는 것이 아니기 때문이다.

- 베드로의 모습을 보았으니, 이제는 나도 평소에 계속해 왔던 기도라도 현장에서 꼭 해야겠다. 

