4. 주제만들기: 예수의 이름으로 담대히 전하는 사울

5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 사울을 믿지 못하는 사람들과 제자들
- 사울의 변화로 당혹해하는 유대인들
- 사울을 죽이길 공모하는 유대인들
- 사울을 줄에 달고 성벽에서 내보내는 제자들
- 사울을 두려워하는 사도들에게 대신 말해주는 바나바
- 예루살렘에서 예수를 담대히 전하는 사울
- 사울을 죽이려는 것을 알고 다소로 보내는 형제들 

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 사울의 변화를 보면 당황 할 수 밖에 없다. 불과 며칠전까지만 하더라도 예수를 전하는 자를 죽이려했었지만 예수님을 만나고 예수님을 전하는 사람이 되었다. 
- 유대인들 입장에선 이해가 안됐을 것이다. 그러나 바울의 입장에선 예수를 믿는 자들을 죽이려고 앞장섰던 자신이 예수님을 전하는 것이 큰 영향을 미친다는 것을 알았을 것이다.
- 사울은 예수님을 만나고 사흘 동안 먹지도 마시지도 않았다. 아마 큰 충격을 받았을 것이고, 자신의 죄악을 깨닫고 회개했을 것이다. 그 결과 예수님을 즉시 전하는 사도가 되었다.
- 예수를 전하는 것을 알고 사울을 죽이려하자 그의 제자들은 그를 광주리에 담았다고 되어있다. 짧은 시간, 예수님을 전하면서도 제자를 양육했던 것 같다.
- 사울은 제자 양육을 통해 복음이 더욱 확장되는데 큰 역할을 했다.
- 남북청년연합선교회도 이와 같은 방법과 믿음으로 사역에 힘쓰고 있다.

9. 적용(나): 
- 사울과 같은 믿음과 결단이 생기길 기도한다.
- 남북청년연합선교회의 새 비전이 잘 완성되고, 복음이 확장되는데 귀하게 쓰임 받도록 기도한다. 

10. 영적터치(단어/구절)
- 그의 제자들이

11. 믿음과 회개 및 감사기도로 마무리

