6. 그는 무두장이 시몬의 집에 유숙하니 그 집은 해변에 있다 하더라
7. 마침 말하던 천사가 떠나매 고넬료가 집안 하인 둘과 부하 가운데 경건한 사람 하나를 불러
8. 이 일을 다 이르고 욥바로 보내니라
