- 고넬료의 사람들은 고넬료를 의인이자 하나님을 경외하는자라고 표현했다.
- 고넬료라하면 누구라도 엄지를 지켜들 정도의 인물이었던 것 같다. 
- 고넬료는 베드로를 만날 때 친척과 가까운 지인을 불렀다.
- 복음과 구원을 자신만 누리는게 아니라, 이웃과 함께 하고자 했을 것이다.
- 내가 의롭고, 하나님을 경외하는 모습으로 살아간다면 예수님을 믿지 않는 친척과 지인들이 나의 모습을 믿고 하나님을 믿고자 하는 마음이 생길 것이다.
- 고넬료와 같은 성품과 믿음이 우리에게 필요하다.

