- 하나님께서 깨끗하게 하신 것을 네가 속되다 하지 말라 말씀하심
- 이 일이 세 번 있었고, 베드로는 이 환상에 대해 생각하며 의아해 함
- 고넬료의 사람들이 도착하여 베드로를 찾음
- 베드로가 두 사람을 따라가라는 성령님의 음성을 들음

7.하나님 찾기(해석)
- 큰 사건이 있기 전에 하나님께서 환상을 보여주시고 마음의 준비를 하게 하셨다.
- 사람이 그동안 쌓아온 세계관과 지식, 규범 등이 깨지는 것은 불가능에 가깝기 때문에 하나님께서 개입하시는 듯 하다.
- 두 사람이 베드로를 만나기 전에 성령께서 베드로에게 두 사람을 따라가라고 말씀해 주심
- 이렇게 말씀하시지 않았다면, 교회가 박해를 받는 상황이었기에 베드로는 낯선 사람이 찾아왔을 때 피신하였을 것이고, 또한 베드로를 유숙하게 한 시몬은 베드로를 숨기려 했을 것이다.
- 성령님께서 내가 그들을 보내었느니라 라고 보증을 서 주시니 베드로는 크게 안심되었을 것이다.
 
8.인간 찾기(해석)
- 베드로가 기도 중에 환상을 보았다. 
- 때가 되어서 환상을 보여주신 것이기도 하지만, 베드로가 기도 중에 환상을 보았다는 것을 우리는 기억해야 한다.
- 환상 중에 주님께서 부정한 음식을 먹으라고 하시니 베드로는 당황할 수 밖에 없었다.
- 유대인들은 정한 동물만 먹는 것이 하나님의 말씀으로 정해진 율법이었기에 베드로는 목숨을 걸고 지켜왔던 터였다.
- 하나님께서 먹지 말라하신 음식을 왜 먹으라 하십니까 저는 평생 부정한 것은 먹지 않았습니다.
- 그때 하나님께서 깨끗하게 하신 것을 네가 속되다 하지 말라는 음성이 들렸다.
- 주님께서 말씀하셨으니 당황하며 세 번이나 같은 말을 한다.
- 베드로는 과연 주님의 말씀이 무슨 뜻인지 깊이 생각하며 고민했을 것이다.

- 고넬료의 사람이 베드로를 찾으러 왔고, 아마도 그들은 군복을 입고 있었을 것이다.
- 고넬료가 로마군의 백부장이기 때문이다.

- 두 사람을 만나기 전에 성령님께서 베드로에게 두 사람을 따라가라고 미리 말씀해 주셨다.
- 성령님께서 말씀해 주시지 않았다면, 군복을 입은 두 사람을 보았을 때 베드로 일행은 크게 놀라 피하려고 했을 것이다.

9.적용(나) 
- 베드로는 정해진 시간에 기도를 하다가 환상을 보았다.
- 나도 시간을 정해놓고 기도를 해야 한다.
- 하나님은 기도하는 자를 통해 역사하신다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-10-03', '사도행전', '10장 31~40절', '&nbsp;', '(사도행전 10장)
31. 말하되 고넬료야 하나님이 네 기도를 들으시고 네 구제를 기억하셨으니
32. 사람을 욥바에 보내어 베드로라 하는 시몬을 청하라 그가 바닷가 무두장이 시몬의 집에 유숙하느니라 하시기로
33. 내가 곧 당신에게 사람을 보내었는데 오셨으니 잘하였나이다 이제 우리는 주께서 당신에게 명하신 모든 것을 듣고자 하여 다 하나님 앞에 있나이다
34. 베드로가 입을 열어 말하되 내가 참으로 하나님은 사람의 외모를 보지 아니하시고
35. 각 나라 중 하나님을 경외하며 의를 행하는 사람은 다 받으시는 줄 깨달았도다
36. 만유의 주 되신 예수 그리스도로 말미암아 화평의 복음을 전하사 이스라엘 자손들에게 보내신 말씀
37. 곧 요한이 그 세례를 반포한 후에 갈릴리에서 시작하여 온 유대에 두루 전파된 그것을 너희도 알거니와
38. 하나님이 나사렛 예수에게 성령과 능력을 기름 붓듯 하셨으매 그가 두루 다니시며 선한 일을 행하시고 마귀에게 눌린 모든 사람을 고치셨으니 이는 하나님이 함께 하셨음이라
39. 우리는 유대인의 땅과 예루살렘에서 그가 행하신 모든 일에 증인이라 그를 그들이 나무에 달아 죽였으나
40. 하나님이 사흘 만에 다시 살리사 나타내시되

