6.인간 찾기(관찰)
- 할례자들에게 설명하는 베드로
- 베드로의 설명을 듣고 하나님께 영광을 돌리는 할례자들
- 흩어진 자들이 유대인에게만 말씀을 전하다가 몇 사람이 안디옥에 이르러 헬라인에게도 주 예수를 전파함

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 이방인 고넬료를 만났다는 이유로 베드로를 비난하는 할례자들에게 베드로가 상황을 자세히 설명함
- 베드로와 함께 간 여섯 명의 사람들까지 있었기에 그들이 증인이 되었을 것
- 베드로의 설명을 들은 할례자들이 성령 하나님의 역사이심을 인정하고, 비난을 멈춤
- 그리고 하나님께 영광을 돌렸는데 이것은 하나님의 크신 사랑과 은혜를 깨달았기 때문이다.
- 선민사상이 깨지는 것은 어려운 일인데 할례자들이 이렇게 받아들이는 것 또한 하나님의 은혜가 아닐 수 없다.

- 스데반 일로 흩어진 제자들에 의해 복음이 계속 전파된다.
- 복음은 멈추지 않고 전진(확장)한다.
- 그리고 안디옥에 이르러 헬라인에게도 복음이 전파되기 시작한다.

9.적용(나) 
- 복음은 성령을 받은 자를 통해 전파된다. 또한 성령님은 복음 전할 사람을 만나게 하신다.

- 복음은 성장한다. 개인적으로도 자라고, 지역적으로 자란다.
- 복음에는 멈추지 않는 전진성과 생명력이 있다.
- 복음에는 믿는 자들에게 구원을 주시는 하나님의 능력이 있다.
- 이것을 믿는 나도 이 복음을 전해야 한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-10-06', '사도행전', '11장 1~10절', '하나님의 시선', '[행11:1-10]
1 유대에 있는 사도들과 형제들이 이방인들도 하나님의 말씀을 받았다 함을 들었더니
2 베드로가 예루살렘에 올라갔을 때에 할례자들이 비난하여
3 이르되 네가 무할례자의 집에 들어가 함께 먹었다 하니
4 베드로가 그들에게 이 일을 차례로 설명하여
5 이르되 내가 욥바 시에서 기도할 때에 황홀한 중에 환상을 보니 큰 보자기 같은 그릇이 네 귀에 매어 하늘로부터 내리어 내 앞에까지 드리워지거늘
6 이것을 주목하여 보니 땅에 네 발 가진 것과 들짐승과 기는 것과 공중에 나는 것들이 보이더라
7 또 들으니 소리 있어 내게 이르되 베드로야 일어나 잡아 먹으라 하거늘
8 내가 이르되 주님 그럴 수 없나이다 속되거나 깨끗하지 아니한 것은 결코 내 입에 들어간 일이 없나이다 하니
9 또 하늘로부터 두 번째 소리 있어 내게 이르되 하나님이 깨끗하게 하신 것을 네가 속되다고 하지 말라 하더라
10 이런 일이 세 번 있은 후에 모든 것이 다시 하늘로 끌려 올라가더라

