6. 인간 찾기 (관찰)
- 총독의 마술사 엘루마의 눈을 멀게 한 사도 바울
- 눈이 먼 사건을 믿고 사도의 가르침에 놀라는 총독
- 안디옥으로 갔고, 안디옥 회당에서 복음 전할 기회를 얻어 복음을 전하는 바울

