8. 인간(해석):
- 성령충만에는 담대함이 따른다. 총독 옆에 권력을 누리던 엘루마는 사도들이 못 마땅했을 것이다. 복음을 전하는 사도들을 사사건건 방해했을 것이 뻔하다.
- 그러자 사도 바울은 엘루마의 눈을 멀게한다. 성령 충만함은 담대함과 강한 믿음을 준다. 
- 한치의 망설임도 없이 선포해버리는 사도 바울의 믿음이 대단하게 느껴진다. 

- 안디옥으로 이동한 일행은 회당에 들어갔다. 회당장이 발언의 기회를 주자 거침없이 복음을 전한다.
- 나에게 주어질 몇 안 되는 전도 기회를 반드시 붙잡아야겠다. 성령충만함으로 사도 바울처럼 담대히 예수님을 전하고 싶다. 

9. 적용(나): 
