5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 바울과 바나바를 신들 중 하나라 여기는 이방인들
- 이 사실을 듣고 옷을 찢으며 소리지르는 바울
- 바울을 돌로 치도록 무리를 충동하는 유대인들
- 죽은 줄 알고 시외로 끝어내자 다시 일어서 성 안으로 들어가 바나바와 함께 더베로가는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 오늘 말씀은 두가지를 생각하게 된다.
- 첫 번째는 복음을 올바르게 받아들이지 못하면, 전도자를 신격화 할 수 있다는 것이다. 
- 이는 복음을 왜곡하게 되고, 하나님보다 전도자를 믿게 된다.
- 현대 교회의 많은 성도들이 하나님보다 전도자를 믿으며, 전도자의 말과 행동에 위로를 얻으려는 경우가 많다. 주의해야할 부분이다.

- 두 번째는 겸손이다. 
- 복음을 전한 바울과 바나바는 자신을 신격화하자 옷을 찢으며 소리쳤다. 
- 자신을 지지하는 사람도 많아졌고, 이방인들 사이에서 최고의 신이라 여기는 이의 호칭도 부른다면 나는 과연 흔들리지 않고 겸손함을 유지할 수 있을지 의문이 든다. 
- 바울은 하나님께로 돌아오게 하는 것이 복음을 전하는 이유라고 분명히 말한다. 
- 인기가 높아질수록 흔들리지 않는 믿음과 변하지 않는 진리의 말씀을 온전히 전할 수 있어야 한다. 

9. 적용(나): 
- 사역자분들을 신격화하고 있진 않은지 점검해야겠다.
- 복음에 겸손함을 유지할 수 있는 능력을 달라고 기도해야겠다.

10. 영적터치(단어/구절)
- 옷을 찢고 무리 가운데 뛰어 들어가서 소리 질러

