이르러: 24절 26절

4. 주제 만들기: 
안디옥 교회로 돌아온 바울과 바나바

5. 하나님 찾기 (관찰)

6.인간 찾기(관찰)
루스드라와 이고니온과 안디옥으로 돌아온 바울과 바나바
제자들의 마음을 굳게 함

7. 하나님 찾기(해석)
 
8. 인간 찾기(해석)
 바울과 바나바는 자신의 목숨보다 복음 전파를 더욱더 귀하게 여겼다. 

바울은 이고니온에서 온 유대인들에게 돌에 맞아 쓰러졌다. 

죽은 것으로 여김을 받은 바울은 성 밖으로 던져졌지만 깨어나자마자 곧바로 성안으로 다시 들어가 전도하였다. 

그리고 이후에 루스드라와 이고니온과 안디옥으로 돌아가서 하나님이 그들을 통해 행하셨던 사역을 나누었다. 

이고니온은 사실 위험한 장소이다. 그곳에는 바울을 끝까지 추적하여 돌로 쳤던 포악한 유대인들이 있기 때문이다. 

그런데도 바울과 바나바는 다른 영혼의 구원과 제자들의 믿음을 다지는 일에만 관심이 있었다. 

바울과 바나바의 영혼을 사랑하는 마음을 보면 큰 도전을 받는다. 한 영혼이 구원받기 위해서는 누군가가 큰 대가와 희생을 통하여 생겨남을 알 수 있다. 

우리 대한민국도 과거 수많은 외국 선교사님이 가족들을 잃으면서도 복음을 전파한 덕분으로 지금 기독교 비율이 높은 국가가 되었다. 

감사한 일이다. 그들 덕분에 나도 지역교회의 전도로 주님을 믿는 데 영향을 받았다. 받은 사랑 간직하고 빚진 사람의 마음으로 열심히 복음을 전파하는 삶을 살아내야겠다.

9. 적용:
우리 남청년(남북 청년 연합선교회)에서 준비하는 일본선교를 위하여 오늘 시간을 내어 간절히 기도해야겠다. 


10. 영적 터치 (단어 또는 구절)
