8. 인간 찾기(해석)
초대교회는 영적 질서가 자리 잡고 있음을 알 수 있다.

구원과 관련해서 논쟁(이방인의 모세의 율법과 할례)이 있었을 때 안디옥교회에 있던 바울과 바나바는 예루살렘 교회의 영적 권위를 인정하고 받아들였다.

예루살렘 교회의 출발은 사도나 장로로부터  시작된 것은 아니었다.

분명한 성령 체험을 허락하신 성령 하나님의 인도하심인 것을 깨우친다.

베드로와 바울 그리고 바나바는 이방인에 대한 구원에 대하여 각각 성령 하나님의 인도하심을 경험하였다.

그럴 뿐만 아니라 그 외 사림들도 그와 같은 음성을 들었다.

28절에 보면 "성령과 우리는" 기록된 것처럼 모두가 성령님을 의존하고 있음을 본다.

영적 질서는 각 교회 목사님으로부터 출발하는 것이 아니라 성령 하나님의 권능으로부터 시작된다.

우리 남 청년(남북 청년 연합선교회)도 마찬가지로 성령님의 주권으로 질서가 잡힌다.

성령 하나님은 한 성령님으로서 혼란과 분열을 막으시고 공동체와 개인에게 안정과 평안하게 해 주심을 알 수 있다.

그분은 우리 공동체의 주인이시고 왕이시다. 또한 그분은 흠이 없으시고 완벽하시다.

이러한 모습을 보면 성령 충만함을 위하여 노력하는 삶이야말로 선택이 아닌 의무요 신자의 특권임을 깨우친다.

9. 적용
오늘도 성령 충만함을 받기 위하여 더욱 간구해야겠다.

10. 영적 터치 (단어 또는 구절)
28절: 성령과 우리는 이 요긴한 것들 외에는 아무 짐도 너희에게 지우지 아니하는

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

