6. 인간 찾기 (관찰)
- 주의 말씀을 간수와 집에 있는 모든 사람에게 전하는 간수
- 간수는 바울을 집으로 데려가 맞은 자리를 씻겨주고 자신과 온 가족이 세례를 받음
- 온 집안이 하나님을 믿으므로 기뻐함
- 상관들이 부하를 시켜 바울을 풀어주라 명함
- 바울은 로마 사람을 죄도 정하지 않고 때리고 옥에 가두었다가 그냥 보내고자 하느냐며 따짐
