- 성령 하나님이 주신 마음으로 지혜롭게 하나님을 변증하고 예수님의 부활을 선포했고, 몇 사람이 믿고 따랐다.
- 성령 하나님께서는 바울을 아테네로 인도하셔서 이 몇 사람을 구원하셨다.

- 똑같은 말을 듣고 어떤 사람은 믿고 구원을 받지만, 어떤 사람들은 듣고자 하지 않으며, 어떤 사람들은 듣기는 하지만 말이 안 된다고 생각하고 믿지 않는다.
- 복음을 전하는 것도 성령님의 도우심으로 하는 것이고, 복음을 받고 믿는 것도 성령님의 도우심이 없으면 할 수 없는 것이다.
