- 감사하며 성령님의 도우심을 구하며, 늘 복음을 전하고자 하는 마음 자세로 살아야 한다.

- 복음을 전할 때 본문에서 바울이 설교하는 내용처럼 하나님을 말하고, 예수님의 부활을 전하면 논리적으로 부족함이 없을 것이다.

