12. 갈리오가 아가야 총독 되었을 때에 유대인이 일제히 일어나 바울을 대적하여 법정으로 데리고 가서
13. 말하되 이 사람이 율법을 어기면서 하나님을 경외하라고 사람들을 권한다 하거늘
14. 바울이 입을 열고자 할 때에 갈리오가 유대인들에게 이르되 너희 유대인들아 만일 이것이 무슨 부정한 일이나 불량한 행동이었으면 내가 너희 말을 들어 주는 것이 옳거니와
