- 바울(1,4,5,6,9,10절)
- 유대인(3절)
- 생업(3절)

4. 주제만들기: 동일한 복음, 다른 선택

5. 하나님 찾기 (관찰)
- 밤에 바울에게 나타나셔서 두려워하지 말고 침묵하지 말고 말하라고 말씀하심
- 너와 함께 있으매 어떤 사람도 너를 대적하거나 해롭게 할 자가 없고 이 백성 중에 내 백성이 많다고 말씀하심

6. 인간 찾기 (관찰)
- 아덴을 떠나 고린도에가서 아굴라와 브리스길라를 만나 생업을 함께하며 동역하는 바울
- 안식일마다 회당장에서 강론하는 바울
- 하나님의 말씀에 붙잡혀 예수를 그리스도라 전하는 바울
- 대적하는 고린도 사람들
- 하나님을 경외하는 디도의 집으로 들어가서 지내며 회당장 그리스보에게 복음을 전하는 바울
- 환상을 보는 바울

7. 하나님 찾기 (해석)
- 혼자 외로이 긴 시간 복음을 전하는 바울에게 하나님은 두려워말라고 말씀하셨다.
- 바울에게 얼마나 큰 위로가 되었을까?
- 하나님께선 우리를 방치하지 않으신다. 우리를 위로하시며, 담대하게 하시며, 용기를 주는 분이시다.  

8. 인간(해석):
- 복음을 들은 사람들 중 복음을 받아들인 사람이 있고, 대적한 사람들이 있다. 
- 복음을 받아들인 사람들은 그들이 특별해서 복음을 받아들인 것은 아니다. 모든 것은 하나님의 은혜이다.
- 그러므로 우리는 복음을 받아들일 수 있음에 감사하고, 다른 이에게 복음을 전할 수 있어야한다. 
- 복음을 받아들이지 못한 사람들에겐 긍휼한 마음이 생겨야한다. 그들이 안타까워야하며, 하나님의 때에 복음을 받아들이길 간절히 기도할 수 있어야 한다.
- 복음을 전하고 긍휼한 마음을 가질 수 있길 소망한다.

9. 적용(나):
- 노방전도를 꾸준히 이어가고, 믿지 않는 사람을 위해 기도해야겠다. 

10. 영적터치(단어/구절)
두려워하지 말며 침묵하지 말고 말하라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-11-01', '사도행전', '18장 21~28절', '제목 없음', '(사도행전 18장)
21. 작별하여 이르되 만일 하나님의 뜻이면 너희에게 돌아오리라 하고 배를 타고 에베소를 떠나
22. 가이사랴에 상륙하여 올라가 교회의 안부를 물은 후에 안디옥으로 내려가서
23. 얼마 있다가 떠나 갈라디아와 브루기아 땅을 차례로 다니며 모든 제자를 굳건하게 하니라
24.  알렉산드리아에서 난 아볼로라 하는 유대인이 에베소에 이르니 이 사람은 언변이 좋고 성경에 능통한 자라
25. 그가 일찍이 주의 도를 배워 열심으로 예수에 관한 것을 자세히 말하며 가르치나 요한의 세례만 알 따름이라
26. 그가 회당에서 담대히 말하기 시작하거늘 브리스길라와 아굴라가 듣고 데려다가 하나님의 도를 더 정확하게 풀어 이르더라
27. 아볼로가 아가야로 건너가고자 함으로 형제들이 그를 격려하며 제자들에게 편지를 써 영접하라 하였더니 그가 가매 은혜로 말미암아 믿은 자들에게 많은 유익을 주니
28. 이는 성경으로써 예수는 그리스도라고 증언하여 공중 앞에서 힘있게 유대인의 말을 이김이러라

