- 요한의 세례(3,4절)
- 세례(3,5절)
- 성령(2,6절)
- 강론(8,9절)

4. 주제만들기: 날마다 들어야 할 복음

5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 아볼로가 고린도 머물고 에베소로 가는 바울
- 에베소에서 어떤 제자를 만났고, 성령과 세례를 알지 못하자 복음(예수)를 전하고 예수의 이름으로 세례를 주는 바울
- 성령이 임하사 방언과 예언을 하는 제자들
- 회당에 들어가 석달동안 하나나님 나라에 대해 강론하는 바울
- 어떤 사람은 마음이 굳어 순종하지 않고 어떤 사람은 비방하자 그들을 떠나 제자들을 세우고 두란노 서원에서 날마다 강론하는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 아볼로의 성장은 바울을 자유롭게 했다. 에베소로 이동해 복음을 전할 수 있게 된 것이다. 
- 남청연의 리더십과 임원진의 성장은 복음이 자유로워질 수 있는 동력이 될 것이다. 
- 바울은 회당에 들어가 석달 동안이나 강론했다. 석달 동안 하나님의 말씀을 들었음에도 깨닫지 못하고 순종하지 못하는 사람들이 있다. 
- 그것이 나일 수 있다. 예배와 말씀을 드리지만 하나님의 말씀을 깨닫지 못하고 형식적인 예배, 형식적인 말씀, 형식적인 기도 생활을 할 수 있다. 스스로에 대한 냉정한 점검이 필요하다.
- 바울은 두해 동안이나 이와 같이 강론했다. 하나님의 말씀을 전하는 일에 몰입한 것이다. 
- 두해가 지나자 유대인이나 헬라인이 다 주의 말씀을 듣게 됐다. 
- 복음을 전할 때 시간이 필요하다. 복음을 받아들이는 시간은 저마다 다르기에, 우리는 인내하는 힘과 능력이 필요하다. 
- 무엇을 하든지 지치지 말아야겠다.

9. 적용(나):
- 나 스스로를 점검해보고 복음을 전하는 일에 지치거나 포기하지 말아야겠다. 

10. 영적터치(단어/구절)
- 두란노 서원에서 날마다 강론하니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-11-03', '사도행전', '19장 11~20절', '능력있게 퍼져나가는 복음', '사도행전 19장
11   하나님이 바울의 손으로 놀라운 능력을 행하게 하시니
12   심지어 사람들이 바울의 몸에서 손수건이나 앞치마를 가져다가 병든 사람에게 얹으면 그 병이 떠나고 악귀도 나가더라
13   이에 돌아다니며 마술하는 어떤 유대인들이 시험삼아 악귀 들린 자들에게 주 예수의 이름을 불러 말하되 내가 바울이 전파하는 예수를 의지하여 너희에게 명하노라 하더라
14   유대의 한 제사장 스게와의 일곱 아들도 이 일을 행하더니
15   악귀가 대답하여 이르되 내가 예수도 알고 바울도 알거니와 너희는 누구냐 하며
16   악귀 들린 사람이 그들에게 뛰어올라 눌러 이기니 그들이 상하여 벗은 몸으로 그 집에서 도망하는지라
17   에베소에 사는 유대인과 헬라인들이 다 이 일을 알고 두려워하며 주 예수의 이름을 높이고
18   믿은 사람들이 많이 와서 자복하여 행한 일을 알리며
19   또 마술을 행하던 많은 사람이 그 책을 모아 가지고 와서 모든 사람 앞에서 불사르니 그 책 값을 계산한즉 은 오만이나 되더라
20   이와 같이 주의 말씀이 힘이 있어 흥왕하여 세력을 얻으니라

