2. 본문 성경 읽기(3번)
3. 반복 단어 찾기(형광펜 사용 추천):
소동/요란: 23절 29절
영업: 25절 27절 
아데미의 신상: 24절 26절 28절 
직공들: 24절 25절 27절 28절 
바울: 21절 26절 30절

4. 주제 만들기:
복음을 방해하는 직공들.

5. 하나님 찾기 (관찰)

6. 인간 찾기(관찰)
디모데와 에라스도를 마게도냐로 보낸 바울.
신상을 만들어 영업하는 직공들이 복음 자를 미워함.

 7. 하나님 찾기(해석)

8. 인간 찾기(해석)
복음은 우상을 만들어 그것으로 영업하여 생계를 유지하는 사람들에게 큰 위협으로 다가갔다. 

바울은 목숨을 바쳐 영혼 구원을 하기 위해 고향을 떠나 갖은 고생을 하며 먼 타국에서 주님 사랑을 전했다. 

그때 바울에 대하여 불만을 가진 우상 만드는 직공들은 바울이나 그를 따르는 사람들을 겁박하였다. 

이러한 행태를 보면 가짜 신을 믿는 사람들은 자신의 이익을 위하여 그들이 숭배하는 신을 수단으로 이용하는 것이 확신한다. 

반면에 사도바울처럼 참신이신 주님을 믿고 따르는 사람들은 예수님의 십자가 사랑을 믿고 부활과 영원한 천국을 믿는 사람으로서 영혼 구원을 위해서 주님의 길을 걷는 사람들이다. 

그런데도 현대 기독교인 중에 혹시 잘못된 신앙심으로 하나님을 자신의 세속적 성공의 도구로 이용하는 사람들이 많을까 두렵다. 

그들 또한 어쩌면 무늬만 기독교인일 수 있다. 나도 내 마음속에 나의 편안과 안전을 지키기 위하여 섬김과 헌신이 식지 않았는지 더욱 점검해야겠다.

 9. 적용:
순수하고 거룩한 복음을 잘 전파하며 주님을 잘 섬기는 충성된 종이 되도록 오늘 기도 모임 때 기도해야겠다. 

