8. 인간(해석):
- 사도행전을 이끄는 인물은 사도 바울이다. 사도 바울은 현대를 살고 있는 우리에게 귀한 도전이 된다. 
- 누구나 사도 바울을 꿈꾸지만 괜찮다. 사도 바울의 사역은 혼자만 이룬 것이 아니다.
- 그의 주변엔 베뢰아 사람 부로의 아들 소바더와 데살로니가 사람 아리스다고와 세군도와 더베 사람 가이오와, 디모데와 아시아 사람 두기고와 드로비모가 있었다. 
- 그들과 함께하며 하나님의 선한 일을 이룬 것이다. 

- 남북청년연합의 주인공은 하나님이시다. 우리는 하나님을 돕는 선한 일꾼이 되어야 한다. 
- 사도 바울과 같은 열정을 품고, 각자의 역할을 성실히 해나가는 남청년이 되길 소망한다.

9. 적용(나): 
