2025년 11월 12일
사도행전 21장 11절~20절
1.1분기도
2. 본문 성경 읽기(3번)
3. 반복 단어 찾기(형광펜 사용 추천):
수족을 잡아매고/손에 넘겨 주리라/결박/죽을: 11절 13절
