5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 바울이 모세를 배반하고, 할례를 금하고, 유대의 관습을 지키지 말라고 가르친다는 소문이 예루살렘에 돌고 있음을 말하는 야고보와 장로들.
- 이 소문을 잠재우기 위해 네 사람과 함께 정결 예식을 행하고 비용을 지불하라고 말하는 야고보와 장로들
- 네 사람과 함께 정결 예식을 행한 바울
- 그러나 아시아에서 온 유대인들이 모든 무리를 충동하여 바울을 붙잡고,
- 거짓 죄명을 씌워 성전 밖으로 끌고 감.

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 야고보와 장로들이 바울에 대한 잘못된 소문을 바로 잡기 위한 방법을 제안함.
- 야고보와 장로들이 바울의 안전을 위해 노력한 것.
- 그러나 이 조치는 구원이 위로 말미암지 않고 오직 은혜로 받는 것임을 유대인이 받아들이는 것에 걸림돌이 된 조치였다.

- 바울이 야고보와 장로들의 말대로 정결 예식을 행하고 그 기한이 차기를 기다림.
- 복음을 전하는 데 있어서 목숨까지도 아끼지 않는 바울이지만, 야고보와 장로들의 말을 따름

- 아시아에서 온 유대인들이 거짓으로 소동을 일으키고 바울을 붙잡아 성전 밖으로 끌고 감.
- 바울이 붙잡히고 박해를 받는 것은 예언이 이루어진 것이지만,
- 이를 행하는 자들을 보면 항상 거짓을 이용하여 소동을 일으키는 것을 알 수 있다.
- 복음을 전하는 사람들은 자신은 언제든지 공격당할 수 있음을 생각하고 있어야 한다.
- 세상은 복음을 전하는 자를 좋게 바라보지 않으며, 복음을 전하는 자를 공격하려 한다.
- 세상은 그렇게 돌아간다.
 
9.적용(나) 
- 기독 동아리를 만들거나 재능기부를 할 때 곱지 않은 시선으로 바라보거나, 다른 꿍꿍이가 있겠지 하는 사람들이 있다.
- 심지어 신자 중에서도 일부 미성숙한 사람들은 이런 것들을 흉보기도 한다.
- 성경을 많이 읽는 것도 시간 낭비라고 하는 신자도 있으니, 하물며 복음 전도는 어떻겠냐마는.
- 복음이 전해지는 데는 여러 가지 모양의 비난과 핍박이 있다는 것을 기억하고 우리는 묵묵히 우리의 길을 걸어가야 한다. 세상은 원래 그렇다. 우리는 뚫고 가야 한다.
- 바울은 목숨도 아끼지 않았다.

10.영적 터치(단어/구절)

