2025년 11월 19일
사도행전 23장 11절~20절
1.1분기도
2. 본문 성경 읽기(3번)
3. 반복 단어 찾기(형광펜 사용 추천):
증언: 11절(2)
먹지도 아니하고/먹지 않기로: 12절 14절
할 말이 있다 하니/할 말이 있다 하여: 17절 18절
바울: 11절 14절 15절 16절 17절 18절 
천부장: 15절 17절 18절 19절 
죽이기 전에/죽이기로: 12절 14절 15절
청하여/청하자: 15절 17절 18절 20절

4. 주제 만들기:
증언자 바울
5. 하나님 찾기 (관찰)
바울에게 용기를 주시는 예수.
바울에게 로마에서도 증언하기를 말씀하시는 예수. 

6. 인간 찾기(관찰)
바울을 죽이기 전에 물과 음식을 먹지 않겠다고 다짐한 40명.
매복하여 그들의 살해계획을 엿듣고 알려준 바울의 생질.
모든 음모가 천 부장에게 전달됨.

 7. 하나님 찾기(해석)
바울이 공회에서 바리새인과 사두개인들로부터 겨우 큰 위기를 모면했다. 

담대해 보였던 바울이었지만 속으로 두려운 마음이 있었던 것 같다. 

그 날밤 주님께서 바울에게 나타나셨다. 그리고 말씀하신다. 
"담대하라". 

사실 주님께 직접 이러한 음성을 들었던 바울은 얼마나 큰 위로를 받았을까! 

또한 얼마나 기뻤을까! 개인적으로 바울을 크게 존경도 하지만 이러한 부분이 너무 부럽다. 

그만큼 바울이 목숨조차도 아끼지 않고 헌신하는 믿음이 있기에 일어나는 은혜일 것이다. 

주님은 바울에게 예루살렘뿐만 아니라 로마에서도 담대히 복음의 증거 자가 되도록 주문하셨다. 

마침 그때 예루살렘에서는 음식과 물을 전폐하고 바울을 죽이겠다고 각오한 유대인이 40명이나 나타났다. 

그때 바울의 생질이 그 사실을 들었다. 이러한 모습을 보면 주님은 자신이 선택한 사명자는 그냥 허무하게 죽도록 내버려 두지 않으신다. 

환경과 주변 사람을 모두 동원해서라도 보호하여 주신다. 

바울이 예루살렘에서 유대인으로부터 핍박당할 때도 주님은 함께하셨고 그 이후 모든 여정 동안 함께하신다는 사실이다. 

우리 남 청년(남북 청년연합 선교회)이 이제 걸음 아를 떼고 주님의 사역을 더욱 감당하는 과정이다. 

풍성한 재정과 더 많은 헌신자 그리고 좋은 환경 등 기도로 해결 받아야 할 일들이 있지만 걱정이나 염려하지 않으려 한다. 

왜냐하면 바울과 함께하신 주님이 우리 남 청년과도 함께하실 것을 믿기 때문이다

8. 인간 찾기(해석)

 9. 적용:
함께하시고 사명자를 지켜주시는 주님을 더욱 찬양합니다. 

오늘도 산기도 가서 주님께 더욱더 감사기도 올려야겠다.

10. 영적 터치 (단어 또는 구절)
11절: 담대하라

11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-11-19', '사도행전', '23장 21~30절', '로마군의 호위를 받으며 로마로 향하는 바울', '사도행전 23장
21   당신은 그들의 청함을 따르지 마옵소서 그들 중에서 바울을 죽이기 전에는 먹지도 않고 마시지도 않기로 맹세한 자 사십여 명이 그를 죽이려고 숨어서 지금 다 준비하고 당신의 허락만 기다리나이다 하니
22   이에 천부장이 청년을 보내며 경계하되 이 일을 내게 알렸다고 아무에게도 이르지 말라 하고
23   백부장 둘을 불러 이르되 밤 제 삼 시에 가이사랴까지 갈 보병 이백 명과 기병 칠십 명과 창병 이백 명을 준비하라 하고
24   또 바울을 태워 총독 벨릭스에게로 무사히 보내기 위하여 짐승을 준비하라 명하며
25   또 이 아래와 같이 편지하니 일렀으되
26   글라우디오 루시아는 총독 벨릭스 각하께 문안하나이다
27   이 사람이 유대인들에게 잡혀 죽게 된 것을 내가 로마 사람인 줄 들어 알고 군대를 거느리고 가서 구원하여다가
28   유대인들이 무슨 일로 그를 고발하는지 알고자 하여 그들의 공회로 데리고 내려갔더니
29   고발하는 것이 그들의 율법 문제에 관한 것뿐이요 한 가지도 죽이거나 결박할 사유가 없음을 발견하였나이다
30   그러나 이 사람을 해하려는 간계가 있다고 누가 내게 알려 주기로 곧 당신께로 보내며 또 고발하는 사람들도 당신 앞에서 그에 대하여 말하라 하였나이다 하였더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
당신: 21(2), 30(2)
바울: 21, 24
유대인: 27, 28
고발: 28, 29, 30

4.주제 만들기: 로마군의 호위를 받으며 로마로 향하는 바울

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 바울의 생질이 천부장에게 유대인들이 바울을 죽이려고 매복한 사실을 알림
- 천부장이 청년에게 이 사실을 알게 된 것을 알리지 말라고 함
- 천부장이 백부장 둘을 불러 무장을 하고 바울을 짐승에 태워 총독에게 갈 것을 명령함    
- 천부장이 총독에게 편지를 써서 보냄

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 바울의 생질이 천부장에게 가서 바울의 위험을 알리고 천부장이 이것을 받아들였는데,
- 만약 바울이 로마 시민이 아니었다면 바로 거절당했을 것임
- 바울의 생질이 매복한 사실을 알게 된 것도 바울이 로마 시민인 것도 모두 하나님의 놀라움 섭리 속에 있음

- 천부장이 정보가 새나가지 않도록 청년에게 이 사실을 함구할 것을 조치하고,
- 즉시 백부장을 불러 병력을 무장하고 바울을 호위할 것을 명령함
- 나아가 바울을 태우고 갈 짐승을 준비하라고 함
- 바울은 로마에 복음을 전하러 가야하는데, 
- 이 사건 없이 스스로 갔다면 자비량이기 때문에 비용도 많이 들고 험한 길을 가야 하기 때문에 체력도 많이 써야 했음.
- 그러나 하나님의 도우심으로 인해 로마 국비로 로마에 복음을 전하는 국비선교사가 되었음.  
- 하나님께서는 바울을 로마에 보내시되, 그냥 보내시지 않고 독수리 날개로 바울을 업어 로마로 이동시키시는 것이다.

- 천부장이 병력 두 개 중대를 보내는 동시에 총독에게 편지를 써서 보냄
- 그의 일처리의 신속함과 치밀함을 알 수 있음
- 그러나 내용을 보면 바울을 심문하기 위해 채찍질하려고 했던 사실을 빼고,
- 자신이 로마 시민인 바울을 구해왔다는 내용만 씀
- 물론 그런 내용까지 구구절절 다 쓸 필요는 없지만, 자신의 잘 한 점만 부각시키는 것은 인간의 본성임

9.적용(나) 
- 지금 고난 중에 있더라도, 
- 사실은 하나님께서 암탉이 알을 품듯이, 
- 독수리 날개를 우리를 업고 날아가듯이,
- 늘 우리를 지키시고 보호하고 계시다는 것을 기억해야 한다.
- 느껴지지 않든, 믿기지 않든, 이것은 사실이다.
- 하나님은 고난과 핍박까지도 합력하여 선을 이루시는 선한 하나님이시다.

- 고난 중일 때 울자, 실컷 울자. 그러나 안아주시는 주님을 바라보자.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-11-20', '사도행전', '23장 31~35절', '총독 앞에서 복음을 전하게 된 바울', '[행23:31-35]
31 보병이 명을 받은 대로 밤에 바울을 데리고 안디바드리에 이르러
32 이튿날 기병으로 바울을 호송하게 하고 영내로 돌아가니라
33 그들이 가이사랴에 들어가서 편지를 총독에게 드리고 바울을 그 앞에 세우니
34 총독이 읽고 바울더러 어느 영지 사람이냐 물어 길리기아 사람인 줄 알고
35 이르되 너를 고발하는 사람들이 오거든 네 말을 들으리라 하고 헤롯 궁에 그를 지키라 명하니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 바울(31,32,33,34절)
- 총독(33,34절)

4. 주제만들기: 총독 앞에서 복음을 전하게 된 바울

5. 하나님 찾기 (관찰)
- 하나님의 뜻 가운데 바울을 로마로 인도하심

6. 인간 찾기 (관찰)
- 바울을 안디바드리에 데리고 가서 기병이 호송하게 인계하는 보병
- 가이사랴에 들어가 총독 앞에 서는 바울
- 어느 영지 사람이냐 묻고 길리기아 사람인 줄 알자 고발한 사람들 앞에서 이야기를 듣겠다 말하는 총독

7. 하나님 찾기 (해석)
- 하나님께서 이루고자 하시면 고난과 어려운 상황 속에서도 복음은 이어진다.

8. 인간(해석):
- 오늘은 기병을 타고 이동하는 바울의 모습이 떠오른다. 담대한 모습인지, 덤덤한 모습인지, 마지막을 생각하는 모습인지 알 수 없다. 
- 두려운 마음이 들 수도 있었지만 하나님께선 직접 말씀해주셨다. “담대하라”
- 하나님께서 직접 응답하신 이 말이 바울에게 얼마나 큰 위로와 힘이 되었을까? 
- 지금 바울 곁엔 아무도 없다. 그러나 외롭지 않았을 것이다. 
- 우리 안에는 성령님이 내주하신다. 우리가 감당해야 할 소명과 삶과 역할 가운데, 선하고 의로운 일을 하는 과정에서 겪는 외로움, 씁쓸함, 갈등은 성령님을 통해 위로받고 용기를 얻을 수 있다. 이게 맞나라는 생각이 들 때 하나님을 더 붙잡아야겠다. 

- 바울은 가이사랴에 들어가 총독을 대면한다. 그리고 자신은 길리기아 사람이라며 자신의 정체성을 드러냈다. 
- 만약 제자 중 누군가 사울의 사명을 담당했다면 관리자들은 그 사람을 무시했을 것 같다. 
- 그러나 바울처럼, 바리새인 중에 바리새인이며, 학식이 뛰어나고, 정체성이 명확한 사람이기에 그의 말을 한번이라도 들어보려는 마음이 들지 않았을까 생각해본다.

9. 적용(나): 
- 하나님을 더욱 의지하고, 맡겨주신 소명에 감사해야겠다.

10. 영적터치(단어/구절)
너를 고발하는 사람들이 오거든 네 말을 들으리라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);